(window.MAP_DATA = window.MAP_DATA || {})["reading_8"] = {"grade":8,"subject":"reading","units":[{"id":"R6","n":6,"title":"RIT 6","goal":"RIT","band":"201–210","skills":["Applies knowledge of Greek or Latin roots in the 6-8 grade band","Determines the cause of an event in literary text","Analyzes dialogue to understand characters","Analyzes how specific details contribute to plot"],"vocab":[],"sets":[{"p":0,"goal":"LT","items":[{"n":1,"t":"mc","s":"Why is the changing room quiet when Hamza receives the armband?","o":["The players are nervous about the match that is about to start.","The players are angry because the coach has left the team.","The players are tired after a long and difficult practice.","The players are surprised because Fahd had expected to be captain."],"k":"D","sk":"Determines the cause of an event in literary text","b":"201–210","g":"LT"},{"n":2,"t":"mc","s":"What does Fahd’s reply “Just give me the ball and stay out of the way” reveal about him?","o":["He wants Hamza to score instead of him in this game.","He thinks the team’s shape is the key to winning.","He trusts mostly in his own ability and dismisses his teammates.","He is nervous about playing in such an important match against a strong team."],"k":"C","sk":"Analyzes dialogue to understand characters","b":"201–210","g":"LT"}],"set":"1"},{"p":1,"goal":"LT","items":[{"n":1,"t":"mc","s":"Why does the date on the letter matter?","o":["It was written the year Rashid was born in the village.","It was written the year Rashid’s father left after the argument.","It was written the week before the farm was sold.","It was written on the day that Rashid’s grandfather first became seriously ill."],"k":"B","sk":"Analyzes how specific details contribute to plot","b":"201–210","g":"LT"},{"n":2,"t":"mc","s":"What was the cause of the conflict between Rashid’s father and grandfather?","o":["They disagreed about whether the father should run the farm or study engineering.","They disagreed about whether the whole family should leave the village and move to Riyadh.","They disagreed about which son should inherit the house.","They disagreed about how to care for the grandfather’s illness."],"k":"A","sk":"Analyzes conflict in literary text","b":"201–210","g":"LT"}],"set":"2"},{"p":2,"goal":"IT","items":[{"n":1,"t":"mc","s":"What is the central idea of the text?","o":["Alexander Fleming discovered penicillin by accident after returning from a holiday.","Mould grows quickly on food that has been left out for too long.","Antibiotics transformed medicine, but their overuse has created a serious new threat.","Soldiers in the Second World War were the first people to use any medicine."],"k":"C","sk":"Determines main/central idea in informational text","b":"201–210","g":"IT"},{"n":2,"t":"mc","s":"According to the text, why did penicillin attract little attention at first?","o":["Fleming did not publish his results anywhere.","The war stopped all scientific research.","Doctors believed mould was too dangerous to use.","Fleming could not produce it in large amounts."],"k":"D","sk":"Determines the cause of a situation","b":"201–210","g":"IT"}],"set":"3"},{"p":3,"goal":"IT","items":[{"n":1,"t":"mc","s":"According to the text, how did most goods travel along the routes?","o":["They were carried by one trader from China to Europe.","They were exchanged only at a single great market.","They were passed from city to city by different traders.","They were sent only by sea to avoid the deserts."],"k":"C","sk":"Locates details in informational text","b":"201–210","g":"IT"},{"n":2,"t":"mc","s":"Which example does the author use to show an idea travelling along the routes?","o":["the trade in frankincense","the markets of Baghdad","the trade in glass and wool","the technique of making paper"],"k":"D","sk":"Identifies evidence that supports a statement","b":"201–210","g":"IT"}],"set":"4"},{"p":4,"goal":"VO","items":[{"n":1,"t":"mc","s":"The root **cred** means “believe.” An **incredible** story is one that —","o":["is easy to remember","is hard to believe","is told by a witness","is written in a book"],"k":"B","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"201–210","g":"VO"},{"n":2,"t":"mc","s":"The root **ject** means “throw.” What does it mean to **reject** an offer?","o":["to change it","to delay it","to accept it","to refuse it"],"k":"D","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"201–210","g":"VO"}],"set":"5"},{"p":5,"goal":"LT","items":[{"n":1,"t":"mc","s":"What lie does Khalid tell his father, and why?","o":["He says the party is on Friday, so that his father will arrive home at exactly the right time.","He says he has a match on Thursday, to keep his father away from the party preparations.","He says he is ill, so that he can stay home and decorate the house.","He says the guests are busy, so that his father will not expect them."],"k":"B","sk":"Explains character motivation","b":"201–210","g":"LT"}],"set":"6"},{"p":6,"goal":"LT","items":[{"n":1,"t":"mc","s":"What do the first two stanzas mainly describe?","o":["the dangers of working near a furnace","the patient process of shaping glass","the history of glassmaking in the region","the speaker’s visit to a glass shop"],"k":"B","sk":"Analyzes how specific parts of a poem contribute to meaning","b":"201–210","g":"LT"}],"set":"7"}]},{"id":"R7","n":7,"title":"RIT 7","goal":"RIT","band":"211–220","skills":["Understands how characters are developed or changed","Uses paragraph-level context to determine word meaning","Determines author’s main argument or claim","Evaluates evidence used to support claims"],"vocab":[],"sets":[{"p":0,"goal":"LT","items":[{"n":1,"t":"mc","s":"How does Hamza’s response at half-time show his leadership?","o":["He stays calm, admits Fahd’s point and challenges him to help the team.","He blames the coach for choosing the wrong players.","He shouts at Fahd in front of everyone and threatens to take him off the field.","He asks the team to give the ball to Fahd every time."],"k":"A","sk":"Analyzes how a character responds to challenges","b":"211–220","g":"LT"},{"n":2,"t":"mc","s":"What does Fahd’s action of passing “on his first touch” show?","o":["He wants the other team to take the ball from him.","He has accepted Hamza’s challenge and is playing for the team.","He is too tired to dribble any more after running so much in the first half.","He has decided to stop trying to score goals."],"k":"B","sk":"Understands how characters are developed or changed","b":"211–220","g":"LT"},{"n":3,"t":"mc","s":"Which theme does the story develop?","o":["Coaches should explain their decisions to the whole team.","The best and most talented player on a team should always be chosen as the captain by the coach.","Real leadership comes from helping others perform well, not from personal talent alone.","Football matches are usually decided in the second half."],"k":"C","sk":"Analyzes the development of theme in literary text","b":"211–220","g":"LT"}],"set":"1"},{"p":1,"goal":"LT","items":[{"n":1,"t":"mc","s":"“He wanted to open it. He also knew it was not his.” What do these sentences show about Rashid?","o":["He has already read the letter in secret.","He wants to keep the letter for himself.","He is curious but respects his father’s privacy.","He is afraid of what the old letter might say about him."],"k":"C","sk":"Determines details that reveal characters’ thoughts","b":"211–220","g":"LT"},{"n":2,"t":"mc","s":"“His father turned it over twice, as if it were very heavy.” What does this comparison suggest?","o":["The father does not recognise the old handwriting at all.","The envelope contains something solid inside.","The father is too weak to hold the letter.","The letter carries great emotional weight for him."],"k":"D","sk":"Interprets simile in context","b":"211–220","g":"LT"},{"n":3,"t":"mc","s":"How has the father changed after reading the letter?","o":["He seems determined to return to the farm at once.","He seems relieved, as if a long burden has been lifted.","He seems confused about what the letter means.","He seems angry that the letter was hidden from him for so long."],"k":"B","sk":"Understands how characters are developed or changed","b":"211–220","g":"LT"},{"n":4,"t":"mc","s":"What lesson does the father draw from the letter?","o":["Family arguments are almost always caused by money and land.","Children should follow their parents’ careers.","Letters are more personal than phone calls.","Important feelings should be expressed before it is too late."],"k":"D","sk":"Determines theme in literary text","b":"211–220","g":"LT"}],"set":"2"},{"p":2,"goal":"IT","items":[{"n":1,"t":"mc","s":"Why does the author begin by describing life before the 1940s?","o":["to explain how Alexander Fleming spent his childhood in Scotland","to show how important antibiotics became by contrasting the past","to describe the work of doctors during the war","to prove that pneumonia is no longer a disease today"],"k":"B","sk":"Analyzes the purpose of an introduction","b":"211–220","g":"IT"},{"n":2,"t":"mc","s":"What causes antibiotic resistance, according to the text?","o":["Overused or unfinished antibiotics let some bacteria survive and pass on resistance.","Mould stops producing penicillin when it is kept in factories.","Doctors prescribe antibiotics that are far too strong for most of their patients to take safely.","Bacteria become weaker each time they meet an antibiotic."],"k":"A","sk":"Analyzes implicit relationships between ideas","b":"211–220","g":"IT"}],"set":"3"},{"p":3,"goal":"IT","items":[{"n":1,"t":"mc","s":"What misunderstanding does the author correct in the first paragraph?","o":["that the routes connected only China and Europe by sea","that the Silk Road was a single highway rather than a network","that traders usually travelled the entire distance","that silk was the only product carried along any of the routes"],"k":"B","sk":"Analyzes how an author introduces and corrects an idea","b":"211–220","g":"IT"},{"n":2,"t":"mc","s":"How does the third paragraph develop the central idea?","o":["It shows that ideas and knowledge travelled along with goods.","It describes how the routes were finally closed.","It explains why the routes were dangerous for traders.","It lists the most valuable goods traded along the routes, from east to west."],"k":"A","sk":"Analyzes how specific paragraphs contribute to meaning","b":"211–220","g":"IT"},{"n":3,"t":"mc","s":"What is the central idea of the text?","o":["The Silk Roads were the most dangerous journeys in history.","The Silk Roads made Arabian merchants the richest in the world.","The Silk Roads connected distant regions, spreading goods, ideas and dangers.","The Silk Roads were mainly used to carry silk from China to the markets of Europe."],"k":"C","sk":"Determines main/central idea in informational text","b":"211–220","g":"IT"}],"set":"4"},{"p":4,"goal":"VO","items":[{"n":1,"t":"mc","s":"Which word has the most NEGATIVE connotation?","o":["scrawny","lean","slim","slender"],"k":"A","sk":"Understands precise connotations of words","b":"211–220","g":"VO"},{"n":2,"t":"mc","s":"Read the paragraph. “The minister’s reply was deliberately **vague**. When reporters asked for dates, he said ‘soon’; when they asked about costs, he said ‘reasonable’.” What does **vague** mean?","o":["long and detailed","quick and confident","not clear or exact","rude and impatient"],"k":"C","sk":"Uses paragraph-level context to determine word meaning","b":"211–220","g":"VO"}],"set":"5"},{"p":null,"goal":"VO","items":[{"n":1,"t":"mc","s":"The root **spect** means “look.” A **retrospective** exhibition looks —","o":["forward to future plans","back at work from the past","around the whole world","closely at one small detail"],"k":"B","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"211–220","g":"VO"},{"n":2,"t":"mc","s":"Read the sentence. “The two sides reached a **compromise**: each gave up something so that they could agree.” What does **compromise** mean?","o":["a victory in which one side wins everything and the other loses","a fight that neither side can win","a promise that is later broken","an agreement in which each side gives something up"],"k":"D","sk":"Uses context to determine word meaning","b":"211–220","g":"VO"},{"n":3,"t":"mc","s":"In which sentence does **novel** mean “a long fictional story”?","o":["She has just published her first novel.","The engineer proposed a novel solution.","It was a novel experience for the team.","They tried a novel way of cooling the hall."],"k":"A","sk":"Determines which meaning of a multiple-meaning word fits","b":"211–220","g":"VO"},{"n":4,"t":"mc","s":"Read the paragraph. “Saad’s apology seemed **insincere**. He smiled while he said it, looked at his phone the whole time and repeated the same mistake the next day.” What does **insincere** mean?","o":["quite short","very polite","not truly meant","too emotional"],"k":"C","sk":"Uses paragraph-level context to determine word meaning","b":"211–220","g":"VO"}],"set":"6"},{"p":5,"goal":"LT","items":[{"n":1,"t":"mc","s":"Which detail in the second paragraph foreshadows the ending?","o":["The father says he might come and watch the match.","The father smiles and returns to the paper.","Khalid nods quickly when asked about the ground.","The father reads the newspaper in the evening."],"k":"A","sk":"Analyzes foreshadowing","b":"211–220","g":"LT"},{"n":2,"t":"mc","s":"“Khalid closed his eyes.” What does this action MOST LIKELY show?","o":["He is tired after a long day of decorating.","He is trying to hear his father more clearly.","He realises how his own lie caused the problem.","He is about to fall asleep in the dark room."],"k":"C","sk":"Makes inferences from literary text","b":"211–220","g":"LT"},{"n":3,"t":"mc","s":"What is the mood at the very end of the story?","o":["sad and lonely","calm and peaceful","tense and frightening","embarrassing but comic"],"k":"D","sk":"Determines mood in context","b":"211–220","g":"LT"}],"set":"7"},{"p":6,"goal":"LT","items":[{"n":1,"t":"mc","s":"“He takes the molten sun of glass.” What does this metaphor emphasise?","o":["the early morning time when the work begins","the round shape of the finished glass object on the shelf","the high price of the glass in the market","the glowing heat and brightness of the melted glass"],"k":"D","sk":"Interprets metaphor in context","b":"211–220","g":"LT"},{"n":2,"t":"mc","s":"“He does not hurry, does not force.” What quality does this line stress?","o":["patience and control","strength and speed","pride and anger","fear and caution"],"k":"A","sk":"Analyzes the effect of repetition and structure","b":"211–220","g":"LT"},{"n":3,"t":"mc","s":"What is the tone of the poem?","o":["angry and bitter","playful and silly","grateful and admiring","anxious and fearful"],"k":"C","sk":"Determines tone in poetry","b":"211–220","g":"LT"}],"set":"8"},{"p":7,"goal":"IT","items":[{"n":1,"t":"mc","s":"What is the author’s main claim?","o":["The city should build more roads to reduce morning traffic.","The city should charge drivers a fee for entering the centre.","The city should make all buses and metro trains free to use.","The city should repair its roads more often to save money."],"k":"C","sk":"Determines author’s main argument or claim","b":"211–220","g":"IT"},{"n":2,"t":"mc","s":"What evidence does the author use to support the first reason?","o":["a comparison between the cost of buses and the cost of cars","a statistic showing exactly how many cars travel along the city’s main roads every day","a quotation from a doctor about the effects of air pollution","the example of Tallinn, where passenger numbers rose after transport became free"],"k":"D","sk":"Evaluates evidence used to support claims","b":"211–220","g":"IT"},{"n":3,"t":"mc","s":"Why does the author describe cars that “crawl” along the roads?","o":["to suggest that drivers are careful and safe","to emphasise how slow and frustrating the traffic is","to describe the shape of the roads in the city","to show that the cars are old and need repair before they break down"],"k":"B","sk":"Analyzes how word choice advances purpose","b":"211–220","g":"IT"}],"set":"9"},{"p":8,"goal":"IT","items":[{"n":1,"t":"mc","s":"What is the author’s claim?","o":["Scientists should study animals only in their natural habitat.","Modern, well-run zoos are essential for protecting wildlife and deserve support.","Families should visit zoos more often than other attractions.","All zoos should be closed immediately because animals suffer badly in captivity."],"k":"B","sk":"Determines author’s main argument or claim","b":"211–220","g":"IT"},{"n":2,"t":"mc","s":"What evidence supports the first reason?","o":["the research scientists do on animal behaviour","the standards that accredited zoos must meet","the return of the Arabian oryx to the wild through breeding programmes","the number of families with young children who visit the city zoo each year"],"k":"C","sk":"Evaluates evidence used to support claims","b":"211–220","g":"IT"}],"set":"10"},{"p":9,"goal":"Literary and Informational Text (paired)","items":[{"n":1,"t":"mc","s":"How is the purpose of Text 1 DIFFERENT from that of Text 2?","o":["Both texts teach readers how to take off in a small plane.","Text 1 conveys the emotion of an experience; Text 2 explains the science behind it.","Text 1 persuades readers to fly; Text 2 warns them about danger.","Text 1 explains the science of flight in detail; Text 2 conveys a young pilot’s emotions."],"k":"B","sk":"Compares and contrasts multiple texts","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":2,"t":"mc","s":"“The ground simply let go of us.” What does this figurative description emphasise?","o":["the noise of the engine as the plane speeds up","the danger of the plane falling back to the ground","the length of the runway beneath the plane","the smooth, almost effortless feeling of take-off"],"k":"D","sk":"Analyzes the effect of figurative language","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":3,"t":"mc","s":"Why does the narrator say the empty seat “looked enormous”?","o":["It emphasises how alone and nervous he suddenly feels.","It shows that the plane was larger than he expected.","It shows that the instructor’s seat was broken.","It explains why the instructor had to leave the plane."],"k":"A","sk":"Determines details that reveal characters’ feelings","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":4,"t":"mc","s":"Which idea is shared by BOTH texts?","o":["Pilots should never fly without an instructor.","Newton’s laws can be felt during take-off.","Wings are central to the experience and science of flight.","Flying is far too dangerous for young and inexperienced pilots to try."],"k":"C","sk":"Determines a shared idea in multiple texts","b":"211–220","g":"Literary and Informational Text (paired)"}],"set":"11"},{"p":10,"goal":"Literary and Informational Text (paired)","items":[{"n":1,"t":"mc","s":"What does the narrator mean by “a calm voice that I knew was not calm at all”?","o":["The mother was angry with Talal for coughing.","The mother was tired and wanted to sleep.","The mother hid her fear to keep Talal calm.","The mother could not speak because of the dust."],"k":"C","sk":"Determines the meaning of a nonliteral phrase","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":2,"t":"mc","s":"How is the purpose of Text 1 DIFFERENT from that of Text 2?","o":["Text 1 argues against air purifiers; Text 2 supports them.","Text 1 shows a family’s experience; Text 2 informs readers about risks and advice.","Both texts are written to persuade people to leave dusty regions.","Text 1 gives medical advice about asthma; Text 2 tells the story of one family’s night."],"k":"B","sk":"Compares and contrasts multiple texts","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":3,"t":"mc","s":"What does the final image of the mother “still sitting beside him” suggest?","o":["that the storm was about to begin again","that she was waiting for the doctor to arrive","that she had fallen asleep in her chair","her devotion and the seriousness of the night"],"k":"D","sk":"Analyzes how an ending contributes to meaning","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":4,"t":"mc","s":"Which detail appears in Text 2 but NOT in Text 1?","o":["Hospitals often report more visits for breathing problems after storms.","Air purifiers can be used to help during dust storms.","Dust can make people cough, wheeze and struggle to breathe during a storm.","People with asthma may need their medicine close by."],"k":"A","sk":"Compares or contrasts details in multiple texts","b":"211–220","g":"Literary and Informational Text (paired)"},{"n":5,"t":"mc","s":"Which idea do BOTH texts support?","o":["Dust storms can be a serious health danger for vulnerable people.","Air purifiers completely prevent all breathing problems.","Dust storms are completely harmless for everyone who stays indoors at home.","People with asthma should never live in dusty regions."],"k":"A","sk":"Determines a shared idea in multiple texts","b":"211–220","g":"Literary and Informational Text (paired)"}],"set":"12"}]},{"id":"R8","n":8,"title":"RIT 8","goal":"RIT","band":"221–230","skills":["Synthesizes information found in multiple texts","Summarizes informational text","Interprets allusion in context","Uses analogies to understand word relationships"],"vocab":[],"sets":[{"p":0,"goal":"LT","items":[{"n":1,"t":"mc","s":"What does Fahd’s comment “For someone who can’t shoot” suggest about the relationship at the end?","o":["Fahd believes Hamza should practise shooting more often.","Fahd respects Hamza now but expresses it with friendly teasing.","Fahd is angry that the team did not win the match.","Fahd still resents Hamza deeply and wants him to lose the armband."],"k":"B","sk":"Makes inferences from literary text","b":"221–230","g":"LT"}],"set":"1"},{"p":1,"goal":"LT","items":[{"n":1,"t":"mc","s":"Which is the BEST objective summary of the story?","o":["Rashid’s father moves to Riyadh, studies engineering and becomes successful, while his grandfather stays in the village.","Rashid opens his grandfather’s desk and discovers many old papers about the history of the family farm.","Rashid finds an unsent letter from his late grandfather and gives it to his father, who learns that the grandfather was proud of him.","Rashid’s grandfather was a stubborn and bitter man who refused for eleven years to forgive his son for choosing engineering over the farm."],"k":"C","sk":"Writes or identifies an objective summary","b":"221–230","g":"LT"}],"set":"2"},{"p":2,"goal":"IT","items":[{"n":1,"t":"mc","s":"How does the section “A Growing Problem” refine the central idea?","o":["It shows that bacteria can no longer cause any serious disease.","It describes how mould is grown in laboratories around the world.","It explains how the team at the University of Oxford purified penicillin for patients.","It adds a warning that the benefits of antibiotics can be lost through misuse."],"k":"D","sk":"Analyzes how specific sections contribute to meaning","b":"221–230","g":"IT"},{"n":2,"t":"mc","s":"Which is the BEST objective summary of the text?","o":["Fleming discovered penicillin in 1928; it became a mass-produced medicine during the war, but overuse of antibiotics has since caused dangerous resistance.","Antibiotic resistance is a serious threat, so people should never take antibiotics, even when a doctor prescribes them.","In 1928, Fleming went on holiday and came back to find mould growing on a dish of bacteria in his laboratory.","Penicillin is the most wonderful medicine ever invented, and everyone in the world should be grateful to Alexander Fleming for his amazing and lucky discovery."],"k":"A","sk":"Summarizes informational text","b":"221–230","g":"IT"}],"set":"3"},{"p":3,"goal":"IT","items":[{"n":1,"t":"mc","s":"Why does the author mention the spread of plague?","o":["to show that connection could bring harm as well as benefits","to prove that most diseases began in China","to describe the medical knowledge carried on the routes","to explain why traders eventually stopped using the routes entirely"],"k":"A","sk":"Analyzes how specific details contribute to meaning","b":"221–230","g":"IT"},{"n":2,"t":"mc","s":"Which sentence BEST summarizes the final paragraph?","o":["The Silk Roads are still used today by traders who cross Asia and Europe with silk and spices.","People should avoid travelling because it spreads disease.","The world is more connected today than it ever was in the past.","The history of the routes shows that global connection has long brought both gains and risks."],"k":"D","sk":"Summarizes informational text","b":"221–230","g":"IT"}],"set":"4"},{"p":4,"goal":"VO","items":[{"n":1,"t":"mc","s":"“When the team learned that the new player was a former champion, they realised they had let a **Trojan horse** into their club.” In a Greek story, soldiers hid inside a wooden horse to enter a city. What does the allusion suggest?","o":["The club had too many members already.","The new player was very fast and strong, so the team became much better.","Something that seemed harmless brought a hidden threat.","The team needed a larger stadium."],"k":"C","sk":"Interprets allusion in context","b":"221–230","g":"VO"},{"n":2,"t":"mc","s":"Which analogy is CORRECT? **Malfunction** is to **machine** as **illness** is to —","o":["body","hospital","doctor","medicine"],"k":"A","sk":"Uses analogies to understand word relationships","b":"221–230","g":"VO"}],"set":"5"},{"p":null,"goal":"VO","items":[{"n":1,"t":"mc","s":"Which word suggests the MOST careful and complete examination?","o":["browse","skim","look around","scrutinize"],"k":"D","sk":"Analyzes nuances in meaning among related words","b":"221–230","g":"VO"},{"n":2,"t":"mc","s":"“Being asked to finish the project in one night was his **Waterloo**.” Waterloo was the battle where Napoleon was finally defeated. What does the allusion suggest?","o":["It was a task that he enjoyed greatly.","It was a task that finally defeated him.","It was a task that he completed easily.","It was a task about European history."],"k":"B","sk":"Interprets allusion in context","b":"221–230","g":"VO"},{"n":3,"t":"mc","s":"Which analogy is CORRECT? **Telescope** is to **far** as **microscope** is to —","o":["bright","heavy","small","loud"],"k":"C","sk":"Uses analogies to understand word relationships","b":"221–230","g":"VO"}],"set":"6"},{"p":5,"goal":"LT","items":[{"n":1,"t":"mc","s":"What makes the ending ironic?","o":["Each person was trying to surprise the other, so the father missed his own surprise.","The guests arrived late and missed the start of the party.","The father forgot that Thursday was his own fiftieth birthday and went out to watch a match.","Khalid’s football team lost a match that he had expected to win."],"k":"A","sk":"Analyzes situational irony","b":"221–230","g":"LT"},{"n":2,"t":"mc","s":"How does the shift to the father’s phone call change the reader’s understanding?","o":["It shows that the guests have gone home without waiting.","It reveals that the father had known about the party all along.","It shows that the father is angry with his son for lying.","It reveals the father’s side of events, which Khalid did not know."],"k":"D","sk":"Analyzes the effect of point of view","b":"221–230","g":"LT"}],"set":"7"},{"p":6,"goal":"LT","items":[{"n":1,"t":"mc","s":"How does the third stanza change the focus of the poem?","o":["It moves the scene from night to morning.","It describes the glassblower’s own childhood in the village.","It connects the glassblower to the speaker’s teacher.","It shows the glass breaking as it cools."],"k":"C","sk":"Analyzes how the organization of a poem affects its meaning","b":"221–230","g":"LT"},{"n":2,"t":"mc","s":"In the poem’s comparison, what does the glass represent?","o":["the classroom, which is hot and bright","the lessons, which are clear and transparent","the teacher, who is fragile and easily broken","the speaker, shaped over time by his teacher"],"k":"D","sk":"Interprets extended metaphor","b":"221–230","g":"LT"},{"n":3,"t":"mc","s":"What does “what I am, I could not see / Until his quiet shaping stirred” suggest?","o":["The speaker discovered his abilities through his teacher’s patient guidance.","The speaker could not see clearly until he finally got new glasses from his teacher.","The speaker wants to become a glassblower himself.","The speaker did not like his teacher at the beginning."],"k":"A","sk":"Determines the meaning of a nonliteral phrase","b":"221–230","g":"LT"}],"set":"8"},{"p":7,"goal":"IT","items":[{"n":1,"t":"mc","s":"Is the Tallinn evidence SUFFICIENT to prove that free transport would reduce traffic in the author’s city?","o":["No; it shows more passengers in one city but not less traffic here.","No; Tallinn never actually made its public transport free.","Yes; it proves that every city in the world would have less traffic.","Yes; it shows that Tallinn has the same roads as this city."],"k":"A","sk":"Evaluates whether evidence is sufficient","b":"221–230","g":"IT"},{"n":2,"t":"mc","s":"How does the author respond to the critics’ counterclaim?","o":["by claiming that the metro does not cost anything to run","by agreeing that free transport is too expensive and that the city should wait many years","by suggesting that drivers should pay for the buses instead","by arguing that fares already cover only part of the cost and other savings would follow"],"k":"D","sk":"Identifies a counterclaim and rebuttal","b":"221–230","g":"IT"},{"n":3,"t":"mc","s":"Which sentence introduces IRRELEVANT evidence?","o":["Fares cover only part of the cost of running the system.","My cousin says the city is very beautiful in winter.","The number of passengers rose after 2013.","Vehicle emissions are a major source of air pollution."],"k":"B","sk":"Recognizes irrelevant evidence","b":"221–230","g":"IT"}],"set":"9"},{"p":8,"goal":"IT","items":[{"n":1,"t":"mc","s":"How does the author respond to the critics?","o":["by admitting some zoos are bad but arguing for better zoos rather than none","by denying that any zoo anywhere has ever treated its animals badly in any way","by agreeing that all zoos should be closed immediately","by saying that animals prefer small enclosures to the wild"],"k":"A","sk":"Identifies a counterclaim and rebuttal","b":"221–230","g":"IT"},{"n":2,"t":"mc","s":"What is the purpose of the phrase “an argument for better zoos, not for no zoos”?","o":["to show that the author agrees completely with the critics about every point","to describe the size of enclosures in modern zoos","to introduce a new reason about education","to turn the critics’ point into support for the author’s position"],"k":"D","sk":"Analyzes the structure of an argument","b":"221–230","g":"IT"},{"n":3,"t":"mc","s":"Which sentence in the final paragraph weakens the argument?","o":["Accredited zoos must meet strict standards for care.","Everyone loves seeing a lion up close.","Scientists learn about animal health and behaviour.","Breeding programmes have helped return animals to the wild."],"k":"B","sk":"Analyzes inadequately supported claims","b":"221–230","g":"IT"}],"set":"10"},{"p":9,"goal":"Literary and Informational Text (paired)","items":[{"n":1,"t":"mc","s":"Which information from Text 2 explains why the plane in Text 1 rolls “faster and faster” before leaving the ground?","o":["A plane must reach a certain speed before its wings produce enough lift.","By Newton’s third law, the air pushes back up on the wing.","A wing is shaped and tilted to push air downward.","Air flowing over the curved top of a wing moves faster than the air below it."],"k":"A","sk":"Synthesizes information found in multiple texts","b":"221–230","g":"Literary and Informational Text (paired)"},{"n":2,"t":"mc","s":"Which term from Text 2 BEST explains what the narrator means when he says the wings were “holding the whole sky underneath them”?","o":["runway","lift","weight","throttle"],"k":"B","sk":"Synthesizes information found in multiple texts","b":"221–230","g":"Literary and Informational Text (paired)"}],"set":"11"},{"p":10,"goal":"Literary and Informational Text (paired)","items":[{"n":1,"t":"mc","s":"Which information from Text 2 BEST explains why Talal’s reaction is more serious than his brother’s?","o":["Dust storms can carry fine particles over very long distances.","Hospitals report more visits after major storms.","For people with asthma, dust can trigger serious attacks.","Most healthy people have only short-lived effects."],"k":"C","sk":"Synthesizes information found in multiple texts","b":"221–230","g":"Literary and Informational Text (paired)"},{"n":2,"t":"mc","s":"Which actions in Text 1 follow the advice given in Text 2?","o":["leaving the house and moving to a relative’s home","covering the windows with wet cloths and fans","going straight to the hospital and calling a doctor to the house","keeping windows shut, using the air purifier and using the inhaler"],"k":"D","sk":"Synthesizes information found in multiple texts","b":"221–230","g":"Literary and Informational Text (paired)"}],"set":"12"}]},{"id":"R9","n":9,"title":"RIT 9","goal":"RIT","band":"231–240","skills":["Evaluates the effectiveness of an argument","Evaluates evidence used to support claims"],"vocab":[],"sets":[{"p":8,"goal":"IT","items":[{"n":1,"t":"mc","s":"Why is the final sentence a weak conclusion?","o":["It relies on feelings rather than the strongest reasons in the argument.","It introduces a counterclaim that is never answered.","It repeats the exact words of the first paragraph without adding anything new.","It provides too many statistics for readers to follow."],"k":"A","sk":"Evaluates the effectiveness of an argument","b":"231–240","g":"IT"},{"n":2,"t":"mc","s":"Which piece of evidence would BEST answer the critics’ concern about suffering?","o":["the price of a family ticket at the city zoo","a list of the most popular animals in zoos around the world and how many visitors see them","a photograph of children smiling at a giraffe","research comparing the health and behaviour of animals in accredited zoos and in the wild"],"k":"D","sk":"Evaluates evidence used to support claims","b":"231–240","g":"IT"}],"set":"1"}]}],"mocks":[{"id":"A","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"The Repair Shop","genre":"story","paras":["Ammar’s uncle owned a small phone repair shop in the old part of Jeddah, and every summer Ammar worked there. He was quick with a screwdriver, and he was proud of it. “Give me ten minutes,” he would tell customers, “and it will be as good as new.”","One afternoon, an old woman brought in a cheap, scratched phone with a cracked screen. “It was my son’s,” she said. “He is working abroad. His voice messages are on it.” She did not need it to be fast or new. She needed it to keep those messages.","Ammar opened the phone in seconds, as usual, but his uncle stopped his hand. “Wait,” he said. “If you rush and damage the memory, we lose more than a screen.” For the next hour, Ammar worked slowly, copying every file before touching a single part. His uncle watched without speaking.","When the woman pressed play and heard her son’s voice, she covered her mouth with her hand. She tried to pay twice the price. Ammar’s uncle refused.","That evening, as they closed the shutters, Ammar said, “I used to think the job was fixing phones.” His uncle smiled. “And now?” Ammar thought for a moment. “Now I think it’s fixing what people care about.”"]},"items":[{"n":1,"t":"mc","s":"What does Ammar’s promise “Give me ten minutes” reveal about him at first?","o":["He takes pride in working quickly.","He is careful and patient with customers.","He does not enjoy working in the shop.","He thinks the phones are too cheap to fix."],"k":"A","sk":"Describes character traits; supporting evidence","b":"201–210","g":"LT"},{"n":2,"t":"mc","s":"What does the woman’s reaction when she hears her son’s voice show?","o":["that she did not expect to pay so much","how deeply the messages matter to her","that the phone is not working properly","that she is unhappy with the repair"],"k":"B","sk":"Determines details that reveal characters’ feelings","b":"201–210","g":"LT"},{"n":3,"t":"mc","s":"Why does the uncle stop Ammar’s hand?","o":["He thinks the phone is too old to be worth repairing.","He wants Ammar to serve another customer first.","He fears that rushing could destroy the messages the woman values.","He wants to repair the phone himself so that he can earn more money from it."],"k":"C","sk":"Explains character motivation","b":"211–220","g":"LT"},{"n":4,"t":"mc","s":"How does Ammar’s understanding of his job change?","o":["from working slowly to working as fast as possible","from trusting his uncle to preferring to work alone","from enjoying repairs in the shop to wanting a completely different career","from fixing devices quickly to caring for what matters to people"],"k":"D","sk":"Understands how characters are developed or changed","b":"211–220","g":"LT"},{"n":5,"t":"mc","s":"Which theme does the story develop?","o":["Speed is the most important skill in any kind of work.","The value of work lies in understanding what people need from it.","Family businesses are always better than large companies.","Old phones should always be replaced instead of being repaired in small shops."],"k":"B","sk":"Analyzes the development of theme in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"The Thief Who Returned the Camel","genre":"folk tale","paras":["One night, a thief crept into the camp of an old Bedouin named Saqr and led away his finest camel. By morning he was far across the desert, but the camel was thirsty, and so was he. At last he saw a tent and asked for water.","The owner of the tent welcomed him, gave him water and dates, and watered the camel. Only when the thief was rested did the man look closely at the animal. It was his own camel. The owner of the tent was Saqr.","The thief went pale and reached for his knife. But Saqr only said, “Keep the camel. But promise me one thing: never tell anyone how you got it.”","“Why?” asked the thief, astonished. “Any other man would want everyone to know of my crime.”","“Because,” said Saqr, “if people hear that a guest was robbed and the host still fed him, they may stop welcoming strangers in the desert. A lost camel can be replaced. Lost hospitality cannot.”","The thief rode away. Three days later, the camel was standing outside Saqr’s tent, tied to the post, with a bag of silver hanging from its saddle."]},"items":[{"n":6,"t":"mc","s":"What situation surprises the thief?","o":["Saqr has followed him all night across the desert.","The tent belongs to another thief hiding in the desert.","The man who feeds him is the owner of the camel he stole.","The camel refuses to drink the water from the well."],"k":"C","sk":"Locates details about plot","b":"201–210","g":"LT"},{"n":7,"t":"mc","s":"Why does Saqr ask the thief to keep the story secret?","o":["He wants to protect the tradition of welcoming strangers.","He does not want the other Bedouin to laugh at him.","He is ashamed that his finest camel was stolen so easily in the night.","He hopes the thief will return and steal again."],"k":"A","sk":"Explains character motivation","b":"211–220","g":"LT"},{"n":8,"t":"mc","s":"What does the thief’s return of the camel show?","o":["The thief could not sell the camel at market.","The camel escaped and walked home alone.","The thief was afraid of being caught.","Saqr’s generosity has changed the thief."],"k":"D","sk":"Understands how characters are developed or changed","b":"211–220","g":"LT"},{"n":9,"t":"mc","s":"Which moral BEST fits the tale?","o":["Generosity can transform even those who have done wrong.","Camels are more valuable than silver or gold.","Thieves are always caught in the end.","Never invite strangers into your home at night, even if they are thirsty."],"k":"A","sk":"Determines the moral of a folk tale","b":"211–220","g":"LT"},{"n":10,"t":"mc","s":"What does Saqr mean by “Lost hospitality cannot” be replaced?","o":["Tents in the desert are difficult to rebuild after storms.","Once people stop trusting strangers, that kindness is hard to restore.","Hospitality costs much more money than a camel does, even for a rich man.","Guests who leave without paying cannot be found again."],"k":"B","sk":"Determines the meaning of a nonliteral phrase","b":"221–230","g":"LT"}]},{"passage":{"title":"Pictures on the Rocks of Ha’il","genre":"informational","paras":["In the Ha’il region of northern Saudi Arabia, two sites, Jabal Umm Sinman near the town of Jubbah and the hills of Al-Manjor and Raat at Shuwaymis, contain thousands of images carved into sandstone. In 2015 they were added to the UNESCO World Heritage List.","The carvings, called **petroglyphs**, were made over many thousands of years. The oldest show human figures and animals such as ibex, horses and wild cattle, some of which no longer live in the region. Later carvings include camels and inscriptions in ancient scripts.","The pictures are more than art. Because they show animals that need more water than the area has today, they provide evidence that the climate was once wetter. They also reveal how people hunted, travelled and perhaps held ceremonies.","Rock art is fragile. Wind, sand and, sadly, people who scratch new marks or names can damage images that have lasted for thousands of years. The sites are now protected, and visitors are asked to look without touching."]},"items":[{"n":11,"t":"mc","s":"What are **petroglyphs**, as used in the text?","o":["maps drawn by travellers","statues made of sandstone","images carved into rock","paintings made on cloth"],"k":"C","sk":"Determines domain-specific word meaning in context","b":"201–210","g":"IT"},{"n":12,"t":"mc","s":"What is the central idea of the text?","o":["Ibex and wild cattle still live in large numbers near Jubbah.","UNESCO adds many sites to its World Heritage List every year.","The Ha’il region is the coldest and wettest part of Saudi Arabia, with many rivers and lakes.","The rock carvings of Ha’il are a valuable record of the past that needs protection."],"k":"D","sk":"Determines main/central idea in informational text","b":"211–220","g":"IT"},{"n":13,"t":"mc","s":"Why does the author include the word “sadly” in the last paragraph?","o":["to express regret that people damage the carvings","to suggest that visitors no longer enjoy the sites","to show that the carvings are about sad events","to explain why the climate became drier"],"k":"A","sk":"Determines author’s attitude in informational text","b":"211–220","g":"IT"},{"n":14,"t":"mc","s":"How is the text organized?","o":["It lists the steps that visitors should follow at the sites.","It tells the story of one archaeologist’s discovery of the carvings in time order.","It compares the carvings of Ha’il with those of another country.","It describes the sites, explains their meaning and then discusses protection."],"k":"D","sk":"Describes the organizational structure of a text","b":"211–220","g":"IT"},{"n":15,"t":"mc","s":"How do the carvings provide evidence about the ancient climate?","o":["They were carved only during the rainy season.","They show animals that need more water than the region has today.","They show rain clouds and rivers flowing past the hills where people lived.","They include written records of the weather each year."],"k":"B","sk":"Analyzes implicit relationships between ideas","b":"221–230","g":"IT"}]},{"passage":{"title":"Harbour at Dawn","genre":"poem","paras":["Before the city lifts its head,","The harbour has been long awake:","The nets are hauled, the gulls are fed,","The engines cough and boat-decks shake.","","The fishermen say little now;","Their hands do all the talking here —","A knot, a hook, a lifted bow,","The language of a working year.","","And when the sun climbs, gold and wide,","And office windows start to burn,","The boats are back, the catch is dried,","And no one thinks to watch their return."],"poem":true},"items":[{"n":16,"t":"mc","s":"“Before the city lifts its head.” What does this personification suggest?","o":["The city is growing taller each year.","The city is looking at the harbour.","The city has not yet woken up.","The city is busy and noisy at dawn."],"k":"C","sk":"Interprets personification in context","b":"201–210","g":"LT"},{"n":17,"t":"mc","s":"“Their hands do all the talking here.” What does this line mean?","o":["The fishermen communicate through their skilled work rather than words.","The fishermen use sign language because they cannot hear over the loud engines.","The fishermen wave to the people in the office windows.","The fishermen argue loudly while they pull in the nets."],"k":"A","sk":"Interprets metaphor in context","b":"211–220","g":"LT"},{"n":18,"t":"mc","s":"What is the theme of the poem?","o":["Fishing is more enjoyable than working in an office.","The best time to go fishing is before sunrise.","Essential work often happens unseen and unappreciated.","Cities should be built far away from busy harbours."],"k":"C","sk":"Determines theme in poetry","b":"211–220","g":"LT"},{"n":19,"t":"mc","s":"What contrast is developed in the final stanza?","o":["between the gold sunrise and the dark night before it","between the noisy engines and the silent fishermen","between the gulls that are hungry at dawn and the fish that are dried by the afternoon","between the fishermen’s finished work and the city that has just started its day"],"k":"D","sk":"Analyzes how specific parts of a poem contribute to meaning","b":"221–230","g":"LT"},{"n":20,"t":"mc","s":"What tone does the last line create?","o":["angry that the fishermen return so late in the day with so few fish","quietly regretful that the fishermen’s work goes unnoticed","joyful that the city welcomes the fishermen home","fearful that the fishermen will not come back"],"k":"B","sk":"Determines tone in poetry","b":"221–230","g":"LT"}]},{"passage":{"title":"Why Do We Need Leap Years?","genre":"informational","paras":["A calendar year has 365 days. But the Earth takes about 365 and a quarter days to travel once around the Sun. That extra quarter of a day may seem small, but it adds up.","If calendars ignored it, they would drift by about one day every four years. After a century, the calendar would be almost a month out of step with the seasons, and summer would gradually begin in what the calendar called spring.","The solution is the **leap year**. Every four years, an extra day, 29 February, is added. Four quarter-days make one whole day, so the calendar catches up.","However, the Earth’s orbit is slightly *less* than 365 and a quarter days. Adding a day every four years over-corrects by a small amount. So the Gregorian calendar has an extra rule: years that end in 00 are not leap years unless they can be divided by 400. That is why 1900 was not a leap year, but 2000 was."]},"items":[{"n":21,"t":"mc","s":"What problem do leap years solve?","o":["Without them, February would have more days than any other month.","Without them, the Earth would orbit the Sun more slowly.","Without them, the calendar would slowly drift away from the seasons.","Without them, the year would end before the Earth finished its orbit."],"k":"C","sk":"Identifies problem-solution as a structure","b":"201–210","g":"IT"},{"n":22,"t":"mc","s":"According to the text, how far would the calendar drift after a century without leap years?","o":["almost a month","about one week","about one day","almost a year"],"k":"A","sk":"Locates details in informational text","b":"211–220","g":"IT"},{"n":23,"t":"mc","s":"How is the text mainly organized?","o":["It compares the Gregorian calendar with the Hijri calendar in every paragraph.","It tells the history of calendars in chronological order.","It gives a list of steps for making a new calendar.","It explains a problem, a solution and then a refinement of that solution."],"k":"D","sk":"Describes the organizational structure of a text","b":"211–220","g":"IT"},{"n":24,"t":"mc","s":"Why does the author put the word *less* in italics?","o":["to make the paragraph look more interesting to readers","to stress a small but important detail that explains the extra rule","to show that the word comes from another language","to show that the author is unsure of the exact length of a solar year"],"k":"B","sk":"Analyzes the purpose of a text feature","b":"221–230","g":"IT"},{"n":25,"t":"mc","s":"According to the rule in the last paragraph, which year WILL be a leap year?","o":["2100","2200","2300","2400"],"k":"D","sk":"Applies information from an informational text","b":"221–230","g":"IT"}]},{"passage":{"title":"How Many Hours on a Phone?","genre":"chart","paras":["**Survey of 120 Grade 8 students: average daily phone use outside school**","Less than 2 hours: 18 · 2–4 hours: 42 · 4–6 hours: 36 · More than 6 hours: 24","Note: Students who reported more than 4 hours also reported, on average, 1.5 hours less sleep per night than students who reported less than 2 hours."]},"items":[{"n":26,"t":"mc","s":"Which group contains the most students?","o":["2–4 hours","less than 2 hours","more than 6 hours","4–6 hours"],"k":"A","sk":"Interprets information in charts or graphs","b":"201–210","g":"IT"},{"n":27,"t":"mc","s":"How many students use their phones for less than 2 hours a day?","o":["18","24","36","42"],"k":"A","sk":"Interprets information in charts or graphs","b":"201–210","g":"IT"},{"n":28,"t":"mc","s":"What percentage of the students use their phones for more than 4 hours a day?","o":["20%","30%","50%","60%"],"k":"C","sk":"Analyzes quantitative information in informational text","b":"221–230","g":"IT"},{"n":29,"t":"mc","s":"Which conclusion is supported by the note?","o":["Phones are the only cause of students losing sleep.","Heavier phone use is associated with less sleep.","Students who sleep less use their phones less.","All students sleep fewer than eight hours a night."],"k":"B","sk":"Evaluates evidence used to support claims","b":"221–230","g":"IT"},{"n":30,"t":"mc","s":"Why would it be a mistake to say the survey PROVES that phones cause poor sleep?","o":["The survey asked about phone use inside school only.","The survey included far too many students for its results to be accurate at all.","The survey shows a connection but not that one thing causes the other.","The survey did not ask any questions about sleep."],"k":"C","sk":"Evaluates reasoning about cause and correlation","b":"231–240","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Read the sentence. “The ancient city was **abandoned**; for centuries no one had lived in its empty streets.” What does **abandoned** mean?","o":["very crowded","left completely empty","newly built","carefully repaired"],"k":"B","sk":"Uses context to determine word meaning","b":"201–210","g":"VO"},{"n":32,"t":"mc","s":"The root **tract** means “pull.” Something that **distracts** you —","o":["makes you tired","helps you focus on your work","gives you energy","pulls your attention away"],"k":"D","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"201–210","g":"VO"},{"n":33,"t":"mc","s":"“The news spread like wildfire.” What does this mean?","o":["The news was about a fire.","The news was false.","The news spread very quickly.","The news caused great damage."],"k":"C","sk":"Interprets simile in context","b":"201–210","g":"VO"},{"n":34,"t":"mc","s":"“After failing the first test, Omar refused to throw in the towel.” What does the idiom mean?","o":["to give up","to celebrate","to clean up","to apologise"],"k":"A","sk":"Interprets idiom in context","b":"201–210","g":"VO"},{"n":35,"t":"mc","s":"The root **voc** means “call” or “voice.” An **advocate** is a person who —","o":["travels to distant countries","stays silent during a debate","writes the rules for a game","speaks in support of a cause"],"k":"D","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"211–220","g":"VO"},{"n":36,"t":"mc","s":"Which word suggests the STRONGEST dislike?","o":["dislike","loathe","avoid","mind"],"k":"B","sk":"Analyzes nuances in meaning among related words","b":"211–220","g":"VO"},{"n":37,"t":"mc","s":"In which sentence does **bear** mean “to carry or support a weight”?","o":["A large brown bear was seen near the river last night.","The old bridge can no longer bear heavy trucks.","Please bear in mind that we leave early.","I cannot bear to watch sad films."],"k":"B","sk":"Determines which meaning of a multiple-meaning word fits","b":"211–220","g":"VO"},{"n":38,"t":"mc","s":"“His explanation was as clear as mud.” What does this ironic simile mean?","o":["His explanation was very simple.","His explanation was perfectly correct.","His explanation was about the weather.","His explanation was very confusing."],"k":"D","sk":"Interprets simile and irony in context","b":"211–220","g":"VO"},{"n":39,"t":"mc","s":"Which word has the most POSITIVE connotation?","o":["curious","nosy","meddling","prying"],"k":"A","sk":"Understands precise connotations of words","b":"211–220","g":"VO"},{"n":40,"t":"mc","s":"The prefix **mal-** means “bad.” **Malnutrition** is a condition caused by —","o":["too much exercise and too little rest","a lack of sleep","poor or insufficient food","a common cold"],"k":"C","sk":"Uses a defined root and/or affix to determine word meaning","b":"211–220","g":"VO"},{"n":41,"t":"mc","s":"Which word BEST completes the sentence? “The scientists repeated the experiment three times; ___, their results were the same each time.”","o":["moreover","however","instead","otherwise"],"k":"A","sk":"Words that show an additive relationship","b":"221–230","g":"VO"},{"n":42,"t":"mc","s":"Read the paragraph. “The new manager was **candid** with the staff. She told them plainly that profits had fallen and that difficult changes were coming.” What does **candid** mean?","o":["cheerful and funny","secretive and careful","honest and direct","angry and impatient"],"k":"C","sk":"Uses paragraph-level context to determine word meaning","b":"221–230","g":"VO"},{"n":43,"t":"mc","s":"Which analogy is CORRECT? **Credible** is to **believe** as **audible** is to —","o":["see","hear","speak","write"],"k":"B","sk":"Uses analogies to understand word relationships","b":"221–230","g":"VO"}]}]},{"id":"B","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"Neighbours","genre":"poem","paras":["We never spoke for seven years,","Just nods across the garden wall;","I knew his car, his coughs, his cheers","When football games were on — that’s all.","","Then came the night the power failed","And every street went black as ink;","He knocked — a candle, and he sailed","Into my kitchen with a wink.","","We talked till dawn of sons and rain,","Of fathers lost and cities far;","And when the lights came on again,","We left my kitchen door ajar."],"poem":true},"items":[{"n":1,"t":"mc","s":"What was the relationship between the neighbours at first?","o":["formal and competitive","polite but distant","close and friendly","angry and hostile"],"k":"B","sk":"Analyzes how specific parts of a poem contribute to meaning","b":"201–210","g":"LT"},{"n":2,"t":"mc","s":"What event changes the relationship?","o":["a storm that damages the garden wall","a new family moving into the street","a power cut that brings the neighbour to the speaker’s door","a football match on television that both men watch together one evening"],"k":"C","sk":"Identifies events that lead to resolution","b":"201–210","g":"LT"},{"n":3,"t":"mc","s":"“I knew his car, his coughs, his cheers.” What does this line suggest?","o":["The speaker often watched football matches with his neighbour.","The speaker was worried that his neighbour was ill.","The speaker wanted to buy his neighbour’s car.","The speaker knew only surface details about his neighbour."],"k":"D","sk":"Makes inferences from poetry","b":"211–220","g":"LT"},{"n":4,"t":"mc","s":"What is the theme of the poem?","o":["Unexpected moments can turn strangers into friends.","Neighbours should not watch loud football matches.","Power cuts are dangerous and should be prevented.","Old friendships are always better than new ones."],"k":"A","sk":"Determines theme in poetry","b":"211–220","g":"LT"},{"n":5,"t":"mc","s":"What does the open kitchen door in the final line symbolise?","o":["the cold air that comes in after the night","the speaker’s fear that the power will fail again","the friendship that continues after the emergency","the speaker’s wish to be left alone"],"k":"C","sk":"Interprets symbolism in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"The Long Walk Home","genre":"story","paras":["The bus broke down eight kilometres outside the village, and the driver said help would not come until morning. Most of the passengers settled in to wait. Bilal looked at the darkening hills and then at his grandmother, who had been visiting the doctor in town.","“We can walk,” she said. Bilal laughed, thinking she was joking. She was seventy-three, and her knee was the reason they had gone to the doctor. But she was already tying her scarf more tightly.","For the first hour, Bilal walked impatiently ahead, then waited, then walked ahead again. “We’ll never get there at this speed,” he muttered. His grandmother only said, “The road is not going anywhere.”","When the moon rose, she began to point things out: the place where her father had kept goats, the wadi that had flooded in the year Bilal’s mother was born, the stone where travellers used to rest. Slowly, Bilal stopped walking ahead. He began asking questions.","They reached the village after midnight. Bilal’s legs ached, but he was surprised to find that he was sorry the walk had ended. “You knew the road would be slow,” he said. His grandmother smiled. “I knew it would be long,” she said. “Slow was your idea of it.”"]},"items":[{"n":6,"t":"mc","s":"Why does Bilal laugh when his grandmother suggests walking?","o":["He is happy to have an adventure with her.","He believes the village is only a short walk away.","He thinks the bus will be repaired very soon by the driver.","He doubts she can manage the distance with her bad knee."],"k":"D","sk":"Explains character motivation","b":"201–210","g":"LT"},{"n":7,"t":"mc","s":"What does the grandmother’s remark “The road is not going anywhere” suggest?","o":["There is no need to rush, because the destination will still be there.","She wants Bilal to walk even faster than before.","She is lost and does not know which way to go.","The road ahead is blocked, so they will have to turn back toward the town."],"k":"A","sk":"Determines the meaning of a nonliteral phrase","b":"211–220","g":"LT"},{"n":8,"t":"mc","s":"What causes Bilal’s attitude to change during the walk?","o":["Other passengers join them and talk to him.","His grandmother’s stories make the journey meaningful to him.","The bright moonlight makes the rough road much easier for them to see.","He becomes too tired to walk ahead anymore."],"k":"B","sk":"Determines the cause of a change in a character","b":"211–220","g":"LT"},{"n":9,"t":"mc","s":"What does the grandmother mean by “Slow was your idea of it”?","o":["Bilal had wanted to take the slow bus instead of walking.","Bilal walked much more slowly than his grandmother did for most of the journey.","Bilal judged the walk as slow, but its value depended on how he saw it.","Bilal should have known that the walk would take all night."],"k":"C","sk":"Analyzes dialogue to understand theme","b":"221–230","g":"LT"},{"n":10,"t":"mc","s":"Which theme does the story develop?","o":["How we experience a journey depends on what we pay attention to.","Buses in rural areas are often old and unreliable.","Older people should not try to travel long distances on foot at night.","Families should spend more time living in villages."],"k":"A","sk":"Analyzes the development of theme in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"The Missing Exam Paper","genre":"drama","paras":["*(A classroom after school. MR. SAMI, a teacher, stands at his desk. Three students — OMAR, RAYYAN and YOUSEF — sit in front of him.)*","MR. SAMI: The answers to tomorrow’s exam were on this desk at lunchtime. Now they are gone. The three of you were the only students in this room.","OMAR: *(quickly)* I didn’t touch anything. I was reading the whole time.","RAYYAN: *(crossing his arms)* Why would I need the answers? I always get full marks.","YOUSEF: *(after a long pause, quietly)* I saw the paper fall behind the cupboard when the window blew open. I meant to tell you, but you had left.","*(MR. SAMI moves the cupboard. The paper is lying on the floor.)*","MR. SAMI: *(holding up the paper)* So nobody took it. *(He looks at the three boys.)* But I learned something useful today. One of you defended himself, one of you praised himself, and one of you told me what happened."]},"items":[{"n":11,"t":"mc","s":"What is the initial conflict in the scene?","o":["The boys are arguing loudly about which of them deserves to get full marks.","The teacher has forgotten to write the questions for the exam.","The window has broken and the classroom must be repaired.","The teacher suspects that one of the boys has taken the exam answers."],"k":"D","sk":"Identifies conflict in literary text","b":"201–210","g":"LT"},{"n":12,"t":"mc","s":"What does Rayyan’s response, with the stage direction *(crossing his arms)*, suggest about him?","o":["He is bored and wants to go home early.","He is defensive and proud rather than helpful.","He is nervous and close to confessing the truth.","He is cold because the window is open."],"k":"B","sk":"Analyzes use of stage directions","b":"211–220","g":"LT"},{"n":13,"t":"mc","s":"Why is Yousef’s answer different from the other two?","o":["He accuses Omar of reading the answers during lunch.","He offers information about what happened instead of focusing on himself.","He admits that he took the paper himself and hid it behind the cupboard.","He refuses to answer the teacher’s questions at all."],"k":"B","sk":"Compares or contrasts characters","b":"211–220","g":"LT"},{"n":14,"t":"mc","s":"What does Mr. Sami mean when he says he “learned something useful”?","o":["The situation revealed each boy’s character.","He learned how to find lost papers quickly.","He learned which boy deserves full marks.","He learned that the window should be locked."],"k":"A","sk":"Determines the meaning of a nonliteral phrase","b":"221–230","g":"LT"},{"n":15,"t":"mc","s":"How is the scene mainly structured?","o":["The events are told through a long flashback from many years later in Mr. Sami’s life.","The scene shows the same event three times from three viewpoints.","A problem is set up, each character responds, and an unexpected solution is revealed.","The scene begins at the end and moves backward to the start."],"k":"C","sk":"Analyzes structure in drama","b":"221–230","g":"LT"}]},{"passage":{"title":"The Beetle That Reads the Stars","genre":"informational","paras":["Dung beetles have an unusual job: they roll balls of animal dung away from crowded piles, where other beetles might steal them, and then bury them as food. To escape competitors quickly, a beetle needs to roll its ball in a straight line.","Scientists had known that dung beetles use the Sun, and even the Moon, to keep their direction. But in 2013, researchers studying beetles in South Africa noticed something surprising: the insects could still roll in straight lines on clear, moonless nights.","To test whether the beetles were using the stars, the researchers took them into a **planetarium**, a building that projects images of the night sky onto a dome. When the dome showed the Milky Way, the beetles rolled in straight lines. When it was dark, they wandered in circles.","The beetles cannot see individual stars well, but they can detect the bright band of the Milky Way. This was the first time any animal had been shown to use the Milky Way to find its way, and it suggests that even small brains can solve surprisingly complex problems."]},"items":[{"n":16,"t":"mc","s":"Why does a dung beetle need to roll its ball in a straight line?","o":["to reach the planetarium before morning","to find the brightest stars in the night sky before the Moon rises","to make the ball of dung larger and rounder","to escape quickly from other beetles that might steal it"],"k":"D","sk":"Determines the cause of a situation","b":"201–210","g":"IT"},{"n":17,"t":"mc","s":"What surprising observation led to the experiment?","o":["Beetles followed the same path as the Sun.","Beetles stopped rolling dung during the daytime and rested in the shade.","Beetles kept a straight path on clear nights without a moon.","Beetles rolled in circles whenever the Moon was full."],"k":"C","sk":"Locates details in informational text","b":"211–220","g":"IT"},{"n":18,"t":"mc","s":"How is the text mainly organized?","o":["as a list of different insects that use the stars","as a question, an experiment and the conclusion drawn from it","as a comparison of dung beetles in South Africa and in the Arabian Peninsula","as a story told from the point of view of a beetle"],"k":"B","sk":"Describes the organizational structure of a text","b":"211–220","g":"IT"},{"n":19,"t":"mc","s":"Why was the planetarium useful to the researchers?","o":["It let them control exactly what the beetles could see in the sky.","It allowed them to take the beetles much closer to the real stars in the sky.","It kept the beetles warm during the long experiment.","It had more dung than the fields in South Africa."],"k":"A","sk":"Analyzes implicit relationships between ideas","b":"221–230","g":"IT"},{"n":20,"t":"mc","s":"Which result supports the conclusion that beetles use the Milky Way?","o":["They could see individual stars more clearly than humans.","They rolled faster when the planetarium was fully lit.","They rolled straight in bright daylight and in total darkness in exactly the same way.","They rolled straight under the Milky Way image but circled in darkness."],"k":"D","sk":"Identifies evidence that supports a statement","b":"221–230","g":"IT"}]},{"passage":{"title":"Let Students Choose Their Books","genre":"argument","paras":["In many schools, every student in a class reads the same assigned novel at the same pace. Teachers mean well, but this approach often turns reading into a chore. Schools should let students choose at least half of the books they read for class.","Choice builds motivation. Studies of young readers have found that students who choose what they read tend to read more and enjoy it more. A student who loves football or space is far more likely to finish a book about it than one he has been told to read.","Choice also allows students to read at the right level. In any class, reading levels can differ by several years. A single assigned book will be too difficult for some and too easy for others.","Some teachers worry that students will choose only easy or poor-quality books. This is a fair concern, but teachers can guide choice by offering a wide but carefully selected library, and by discussing what makes a book worth reading.","When reading feels like a personal discovery rather than an assignment, students become lifelong readers. Surely that is the goal of every English class."]},"items":[{"n":21,"t":"mc","s":"What is the author’s claim?","o":["Teachers should stop assigning any novels to their classes at all from now on.","Students should read only books about sport and space.","Schools should let students choose at least half of their class books.","Every class should read the same book at the same pace."],"k":"C","sk":"Determines author’s main argument or claim","b":"211–220","g":"IT"},{"n":22,"t":"mc","s":"Which reason is supported by the reference to studies of young readers?","o":["Assigned books are always too difficult for students.","Teachers can guide students with a selected library.","Reading levels differ by several years within a class.","Choice builds motivation and leads students to read more."],"k":"D","sk":"Identifies reasons that support a claim","b":"211–220","g":"IT"},{"n":23,"t":"mc","s":"What is the effect of the word “chore” in the first paragraph?","o":["It presents assigned reading as dull, unwanted work.","It shows that students enjoy assigned books.","It suggests that reading is a useful household skill.","It explains how teachers choose class novels."],"k":"A","sk":"Analyzes how word choice advances purpose","b":"211–220","g":"IT"},{"n":24,"t":"mc","s":"How does the author respond to the concern about poor-quality books?","o":["by ignoring the concern and moving on to the conclusion","by suggesting teachers guide choice with a selected library and discussion","by agreeing that students should never choose their own books","by arguing that there are no poor-quality books for students anywhere in the world"],"k":"B","sk":"Identifies a counterclaim and rebuttal","b":"221–230","g":"IT"},{"n":25,"t":"mc","s":"Which evidence would MOST strengthen the second reason?","o":["a list of the most popular novels among teachers","a description of the author’s own favourite childhood book","data showing the range of reading levels in a typical class","a quotation from a famous author about libraries"],"k":"C","sk":"Evaluates evidence used to support claims","b":"221–230","g":"IT"}]},{"passage":{"title":"Express Train Timetable: Riyadh to Dammam","genre":"timetable","paras":["**Riyadh → Hofuf → Abqaiq → Dammam (sample timetable)**","Train 1: Riyadh 06:00 · Hofuf 08:20 · Abqaiq 08:55 · Dammam 09:40","Train 2: Riyadh 10:30 · Hofuf 12:50 · Abqaiq — (does not stop) · Dammam 14:00","Train 3: Riyadh 16:00 · Hofuf 18:20 · Abqaiq 18:55 · Dammam 19:40","*Economy fare Riyadh–Dammam: 80 riyals. Students with ID: 25% discount.*"]},"items":[{"n":26,"t":"mc","s":"How long does Train 1 take to travel from Riyadh to Dammam?","o":["2 hours 20 minutes","3 hours 30 minutes","4 hours 40 minutes","3 hours 40 minutes"],"k":"D","sk":"Interprets information in a timetable","b":"211–220","g":"IT"},{"n":27,"t":"mc","s":"Which train is the fastest from Riyadh to Dammam?","o":["Train 2","They all take the same time.","Train 3","Train 1"],"k":"A","sk":"Integrates information from a text feature","b":"211–220","g":"IT"},{"n":28,"t":"mc","s":"How much does a student with ID pay for an economy ticket from Riyadh to Dammam?","o":["75 riyals","60 riyals","55 riyals","25 riyals"],"k":"B","sk":"Analyzes quantitative information in informational text","b":"211–220","g":"IT"},{"n":29,"t":"mc","s":"A passenger must be in Abqaiq by 15:00. Which train should he take?","o":["none of the trains","Train 3","Train 1","Train 2"],"k":"C","sk":"Integrates information from a text feature","b":"221–230","g":"IT"},{"n":30,"t":"mc","s":"Why is Train 2 faster than the other trains?","o":["It carries fewer passengers.","It does not stop at Abqaiq.","It leaves Riyadh earlier in the day.","It does not stop at Hofuf."],"k":"B","sk":"Makes inferences from informational text","b":"221–230","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"“The classroom was a beehive of activity.” What does this metaphor suggest?","o":["The classroom was very busy.","There were insects in the room.","The students were making honey.","The classroom was very quiet."],"k":"A","sk":"Interprets metaphor in context","b":"201–210","g":"VO"},{"n":32,"t":"mc","s":"“Hassan let the cat out of the bag about the surprise party.” What does this idiom mean?","o":["He freed an animal.","He forgot the party.","He planned the party.","He revealed a secret."],"k":"D","sk":"Interprets idiom in context","b":"201–210","g":"VO"},{"n":33,"t":"mc","s":"The prefix **bi-** means “two.” A **bilingual** person —","o":["lives in two cities","speaks two languages","has two brothers","works two jobs"],"k":"B","sk":"Uses a defined root and/or affix to determine word meaning","b":"201–210","g":"VO"},{"n":34,"t":"mc","s":"The root **ben** means “good” or “well.” A **benevolent** ruler is one who is —","o":["kind and generous","rich and powerful","strict and harsh","young and new"],"k":"A","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"211–220","g":"VO"},{"n":35,"t":"mc","s":"Read the sentence. “The documents were **confidential**, so only the manager was allowed to read them.” What does **confidential** mean?","o":["free to everyone","long and boring","old and damaged","private or secret"],"k":"D","sk":"Uses context to determine word meaning","b":"211–220","g":"VO"},{"n":36,"t":"mc","s":"Which word suggests the MOST extreme happiness?","o":["glad","content","ecstatic","pleased"],"k":"C","sk":"Analyzes nuances in meaning among related words","b":"211–220","g":"VO"},{"n":37,"t":"mc","s":"In which sentence does **draft** mean “an early version of a piece of writing”?","o":["I wrote the first draft of my essay last night.","Sit away from the draft near the window.","The draft from the electric fan made the papers fly.","A cold draft came in under the door."],"k":"A","sk":"Determines which meaning of a multiple-meaning word fits","b":"211–220","g":"VO"},{"n":38,"t":"mc","s":"The root **ject** means “throw.” A **projector** —","o":["prints pages from a computer","throws an image onto a screen","cools the air in a hall","records sounds in a room"],"k":"B","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"211–220","g":"VO"},{"n":39,"t":"mc","s":"Which word BEST completes the sentence? “The plan sounded perfect on paper; ___, it failed completely in practice.”","o":["likewise","consequently","therefore","nonetheless"],"k":"D","sk":"Identifies words in context that show a contrast","b":"221–230","g":"VO"},{"n":40,"t":"mc","s":"Read the paragraph. “Fahad was usually **gregarious**. At every family gathering, he moved from group to group, telling stories and meeting new cousins. That is why everyone noticed when he sat alone.” What does **gregarious** mean?","o":["tired and sleepy","serious and strict","enjoying the company of others","shy, quiet and nervous with strangers"],"k":"C","sk":"Uses paragraph-level context to determine word meaning","b":"221–230","g":"VO"},{"n":41,"t":"mc","s":"Which word has the most NEGATIVE connotation?","o":["clever","cunning","intelligent","bright"],"k":"B","sk":"Understands precise connotations of words","b":"221–230","g":"VO"},{"n":42,"t":"mc","s":"“The final question was the Achilles’ heel of the whole exam for most students.” What does the allusion mean?","o":["It was the easiest and shortest question on the whole paper.","It was the longest question in the exam.","It was the weakest point where most students failed.","It was a question about Greek history."],"k":"C","sk":"Interprets allusion in context","b":"221–230","g":"VO"},{"n":43,"t":"mc","s":"Which analogy is CORRECT? **Architect** is to **blueprint** as **composer** is to —","o":["actor","stage","ticket","score"],"k":"D","sk":"Uses analogies to understand word relationships","b":"231–240","g":"VO"}]}]},{"id":"C","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"The Scholarship","genre":"story","paras":["Only one student from the school would win the scholarship to the summer science camp in Dhahran, and everyone knew it would be Sultan or Mansour. Sultan had the best marks. Mansour had the best ideas.","Two days before the final interview, Sultan found Mansour’s notebook on a bench in the playground. Inside were pages of sketches for Mansour’s project: a cheap sensor that warned farmers when soil was too dry. They were brilliant. Sultan’s own project, a neat poster about solar panels, suddenly looked ordinary.","For a moment, he imagined leaving the notebook where he had found it, or putting it somewhere it would not be found until after the interview. Nobody would know.","Instead, he walked to Mansour’s classroom and handed it over. Mansour’s face went white, then flooded with relief. “I’ve been looking everywhere,” he said. “Thank you.”","Mansour won the scholarship. Sultan did not. But a week later, Mansour knocked on his door with a box of parts. “The sensor needs someone who’s good at maths,” he said. “I’m not. Will you build it with me?”"]},"items":[{"n":1,"t":"mc","s":"How are Sultan and Mansour DIFFERENT as students, according to the first paragraph?","o":["Sultan works alone, while Mansour leads a team.","Sultan has the best ideas, while Mansour has the best marks.","Sultan studies science, while Mansour prefers art.","Sultan has the best marks, while Mansour has the best ideas."],"k":"D","sk":"Compares or contrasts characters","b":"201–210","g":"LT"},{"n":2,"t":"mc","s":"Why does Sultan’s own project “suddenly” look ordinary?","o":["He has lost part of his project in the playground.","He compares it with Mansour’s brilliant and practical design.","His teacher has told him that the poster is not good enough.","He realises he has made a serious mistake in his work."],"k":"B","sk":"Determines the cause of a change in a character","b":"211–220","g":"LT"},{"n":3,"t":"mc","s":"What is the central conflict of the story?","o":["Sultan cannot decide which project to present at the camp.","Sultan and Mansour argue loudly in the playground about which project is better.","Sultan is tempted to gain an advantage by hiding his rival’s notebook.","Mansour accuses Sultan of stealing his ideas."],"k":"C","sk":"Analyzes conflict in literary text","b":"211–220","g":"LT"},{"n":4,"t":"mc","s":"“Mansour’s face went white, then flooded with relief.” What does this description show?","o":["how frightened he had been and how grateful he now feels","that he is angry that Sultan read the notebook","that he is ill, feels weak and needs to see a doctor at once","that he is embarrassed about his sketches"],"k":"A","sk":"Determines details that reveal characters’ feelings","b":"211–220","g":"LT"},{"n":5,"t":"mc","s":"How does the ending develop the story’s theme?","o":["It shows that the scholarship was not important after all.","It shows that honest people never win competitions.","It shows that Sultan’s honesty leads to a new partnership.","It shows that Mansour feels guilty about winning."],"k":"C","sk":"Analyzes the development of theme in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"The Sultan’s Gardener","genre":"folk tale","paras":["A sultan once had a gardener who planted only date palms. “Why do you waste your time?” the sultan asked one day. “A palm you plant today will not give fruit for years. You are already old. You will never eat from these trees.”","The gardener bowed. “Your Majesty,” he said, “I eat every day from palms that my grandfather planted. I plant these so that someone else’s grandson may eat from them.”","The sultan was pleased with the answer and gave the gardener a gold coin. The gardener bowed again. “You see, Majesty,” he said, smiling, “my palm has already given fruit.”","The sultan laughed and gave him a second coin. “And now,” said the gardener, “it has given fruit twice in one year, which no other palm in the kingdom can do.”","The sultan laughed so hard that he gave him a third coin, and then turned to his treasurer. “Take me away from this man,” he said, “before he empties my treasury with his wisdom.”"]},"items":[{"n":6,"t":"mc","s":"Why does the sultan think the gardener is wasting his time?","o":["The gardener is old and will not live to eat the fruit.","Date palms never produce fruit in the kingdom.","The gardener is planting the young palms in the wrong season.","The palms are planted in poor soil."],"k":"A","sk":"Explains character motivation","b":"201–210","g":"LT"},{"n":7,"t":"mc","s":"What does the gardener’s first answer reveal about his values?","o":["He wants the sultan to plant trees himself.","He works for the benefit of future generations.","He works only for the reward of gold.","He prefers palms because they need little water."],"k":"B","sk":"Makes inferences from literary text","b":"211–220","g":"LT"},{"n":8,"t":"mc","s":"What is the main message of the tale?","o":["Old people should not work in gardens.","Date palms are the most valuable trees in a garden.","Rulers should never give gold to their servants, however wise they are.","Wise people act for the future, not only for their own gain."],"k":"D","sk":"Determines theme in literary text","b":"211–220","g":"LT"},{"n":9,"t":"mc","s":"What does the gardener mean when he says his palm “has already given fruit”?","o":["The sultan has bought the palm from him.","The young palm has unexpectedly produced its first dates this year.","His planting has already been rewarded by the sultan’s coin.","He has eaten the fruit of his grandfather’s trees."],"k":"C","sk":"Interprets figurative language in context","b":"221–230","g":"LT"},{"n":10,"t":"mc","s":"What tone does the sultan’s final remark have?","o":["angry and threatening","sad and regretful","confused and suspicious","amused and admiring"],"k":"D","sk":"Determines tone in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"Mountain Road","genre":"poem","paras":["The road to Abha twists and climbs","Like thread pulled loosely through a seam;","It doubles back a hundred times","Above the valley’s cloudy stream.","","My father drives and does not speak;","His hands are steady at the wheel.","Below, the hawks ride out the peak","On currents I can almost feel.","","At every turn, a cliff, a drop,","A village perched on empty air —","And then at last the long climb stops,","And all the world is waiting there."],"poem":true},"items":[{"n":11,"t":"mc","s":"“Like thread pulled loosely through a seam.” What does this simile describe?","o":["the colour of the river in the valley","the twisting, winding shape of the road","the speaker’s nervous feelings","the narrowness of the father’s car"],"k":"B","sk":"Interprets simile in context","b":"211–220","g":"LT"},{"n":12,"t":"mc","s":"What does the second stanza suggest about the father?","o":["He is calm and focused on the difficult drive.","He is angry with the speaker for talking so much.","He is bored and wants to stop the car.","He is lost and unsure of the way."],"k":"A","sk":"Makes inferences from poetry","b":"211–220","g":"LT"},{"n":13,"t":"mc","s":"What feeling does the last line express?","o":["wonder and reward after the difficult climb","boredom with the view from the top","regret that the trip has ended","fear that the long journey is still not finished"],"k":"A","sk":"Determines mood in context","b":"211–220","g":"LT"},{"n":14,"t":"mc","s":"“A village perched on empty air.” What does this image emphasise?","o":["how the village is being built","how high and dramatic the mountain landscape is","how cold the air is in the mountains","how small and poor the village on the mountain is"],"k":"B","sk":"Analyzes the effect of imagery in context","b":"221–230","g":"LT"},{"n":15,"t":"mc","s":"How does the final stanza build to its ending?","o":["It describes the whole journey home again, but in reverse order.","It moves from the speaker’s feelings to the father’s.","It piles up dangers, then releases tension with a sudden view.","It shifts from morning to evening and then to night."],"k":"C","sk":"Analyzes how the organization of a poem affects its meaning","b":"221–230","g":"LT"}]},{"passage":{"title":"Can We Make It Rain?","genre":"informational","paras":["In a country where rain is rare and fresh water is precious, the idea of making clouds give up their water is attractive. Saudi Arabia is one of several countries that have started programmes of **cloud seeding**.","Cloud seeding does not create clouds. It works only when suitable clouds are already present. Aircraft fly into the clouds or below them and release tiny particles, often of salt or a compound called silver iodide. Water droplets or ice crystals gather around these particles, grow heavier and may fall as rain.","Saudi Arabia launched a regional cloud-seeding programme in 2022, with flights over several regions. Supporters hope that even a modest increase in rainfall could help refill underground water supplies and support plants and farming.","Scientists, however, urge caution. It is difficult to prove how much rain was caused by seeding, because no one can know exactly how much would have fallen without it. Results also depend heavily on weather conditions. For this reason, researchers continue to measure and test the method carefully, and most see it as one tool among many, alongside conserving water and desalination."]},"items":[{"n":16,"t":"mc","s":"What is the central idea of the text?","o":["Cloud seeding creates new clouds over dry regions of the Kingdom whenever they are needed.","Saudi Arabia no longer needs desalination because of cloud seeding.","Silver iodide is the most important chemical used in Saudi farming.","Cloud seeding may increase rainfall, but its effects are uncertain and still being studied."],"k":"D","sk":"Determines main/central idea in informational text","b":"211–220","g":"IT"},{"n":17,"t":"mc","s":"Which statement about cloud seeding is supported by the text?","o":["It creates new clouds even in a completely clear and empty sky.","It can be used only over the sea.","It only works if suitable clouds are already present.","It always doubles the amount of rainfall."],"k":"C","sk":"Identifies evidence that supports a statement","b":"211–220","g":"IT"},{"n":18,"t":"mc","s":"According to the text, how do seeded particles help produce rain?","o":["They heat the clouds until all of the water inside them quickly turns into steam.","Droplets or ice crystals gather around them, grow heavier and may fall.","They dissolve the clouds and release all the water at once.","They push the clouds lower so that they touch the ground."],"k":"B","sk":"Understands sequence in informational text","b":"211–220","g":"IT"},{"n":19,"t":"mc","s":"Why is it difficult to prove how much rain seeding causes?","o":["No one can know how much rain would have fallen without it.","The aircraft fly too high for the rain to be measured.","The particles disappear before scientists can test them.","Rain gauges do not work in desert regions."],"k":"A","sk":"Analyzes implicit relationships between ideas","b":"221–230","g":"IT"},{"n":20,"t":"mc","s":"What is the author’s attitude toward cloud seeding?","o":["completely enthusiastic, calling it a perfect solution","strongly opposed, calling it a waste of money","uninterested, giving only a list of facts","balanced, presenting both its promise and its uncertainty"],"k":"D","sk":"Determines author’s attitude in informational text","b":"221–230","g":"IT"}]},{"passage":{"title":"The Manuscripts of Timbuktu","genre":"informational","paras":["In the fifteenth and sixteenth centuries, Timbuktu, in present-day Mali, was one of the great centres of learning in Africa. Scholars, students and traders came to its mosques and schools, and families built private libraries of handwritten books.","These **manuscripts** covered astronomy, mathematics, medicine, law, poetry and history. Many were written in Arabic, and some in local African languages using Arabic script. Families protected them for centuries, often hiding them in wooden chests, in mud houses or underground.","In 2012, armed groups took control of the city. Fearing that the manuscripts would be destroyed, librarians and families secretly moved hundreds of thousands of them out of Timbuktu, hiding them in rice sacks and metal trunks and carrying them by car, boat and donkey cart to the capital, Bamako. Some manuscripts were burned, but most were saved.","Today, scholars are working to preserve and digitise the collection so that its knowledge can be studied around the world. The story of the manuscripts shows that libraries are not only buildings, but communities of people who care about knowledge."]},"items":[{"n":21,"t":"mc","s":"What is the central idea of the text?","o":["Most of the manuscripts of Timbuktu were burned in 2012.","Timbuktu’s manuscripts are a precious record of learning that people risked a great deal to save.","Mali’s capital, Bamako, has the largest library in Africa.","Timbuktu was a busy trading city where merchants from many countries sold rice, cloth and metal trunks."],"k":"B","sk":"Determines main/central idea in informational text","b":"211–220","g":"IT"},{"n":22,"t":"mc","s":"What does the second paragraph show about the manuscripts?","o":["They were mainly about the history of trade in Africa.","They were written only by visiting scholars from other distant countries.","They were stored in a single large library in the city centre.","They covered many subjects and were carefully protected for centuries."],"k":"D","sk":"Analyzes how specific paragraphs contribute to meaning","b":"211–220","g":"IT"},{"n":23,"t":"mc","s":"How is the text mainly organized?","o":["as a comparison of Timbuktu with several other famous African cities and their libraries over time","as a set of instructions for protecting old books","chronologically, from the city’s golden age to efforts to preserve the manuscripts today","as a problem followed by several possible solutions"],"k":"C","sk":"Identifies chronology as a structure","b":"211–220","g":"IT"},{"n":24,"t":"mc","s":"Why does the author list rice sacks, metal trunks and donkey carts?","o":["to show the ordinary, determined methods used to save the manuscripts","to explain how the manuscripts were made","to describe the many different goods that were traded in Timbuktu in the past","to show that the manuscripts were damaged on the journey"],"k":"A","sk":"Analyzes how specific details contribute to meaning","b":"221–230","g":"IT"},{"n":25,"t":"mc","s":"What does the author mean by saying libraries are “communities of people who care about knowledge”?","o":["Only scholars should be allowed to use libraries.","Knowledge survives because people protect and share it, not only because of buildings.","Libraries should always be built in the very middle of communities so that everyone can reach them.","People in Timbuktu lived inside their libraries."],"k":"B","sk":"Determines the meaning of a nonliteral phrase","b":"221–230","g":"IT"}]},{"passage":{"title":"Household Electricity Use","genre":"chart","paras":["**Monthly electricity use in one family home (kilowatt-hours, kWh)**","January: 900 · April: 1,500 · July: 3,600 · October: 1,800","About 70% of the July total was used for air conditioning. The electricity company charges 0.20 riyals per kWh."]},"items":[{"n":26,"t":"mc","s":"How many times greater was July’s use than January’s?","o":["6 times","3 times","4 times","2 times"],"k":"C","sk":"Analyzes quantitative information in informational text","b":"211–220","g":"IT"},{"n":27,"t":"mc","s":"How much did the family pay for electricity in January?","o":["180 riyals","450 riyals","90 riyals","900 riyals"],"k":"A","sk":"Analyzes quantitative information in informational text","b":"211–220","g":"IT"},{"n":28,"t":"mc","s":"About how many kWh were used for air conditioning in July?","o":["3,600 kWh","2,800 kWh","1,080 kWh","2,520 kWh"],"k":"D","sk":"Analyzes quantitative information in informational text","b":"221–230","g":"IT"},{"n":29,"t":"mc","s":"Which explanation BEST accounts for the pattern in the data?","o":["The family travels away from home during the summer months and uses the air conditioning less.","Electricity use rises sharply in the hottest months because of air conditioning.","The family uses more lights during the long winter nights.","Electricity costs more per kWh in July than in January."],"k":"B","sk":"Integrates information from graphics and text","b":"221–230","g":"IT"},{"n":30,"t":"mc","s":"Which change would MOST reduce the family’s July bill?","o":["switching off the oven in October","using fewer lights in the evenings during January","charging phones only at night in April","setting the air conditioning a few degrees higher"],"k":"D","sk":"Integrates information from graphics and text","b":"221–230","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"“My little brother is a walking dictionary.” What does this metaphor suggest?","o":["He knows the meanings of many words.","He cannot read at all yet.","He carries a dictionary everywhere.","He walks around reading books."],"k":"A","sk":"Interprets metaphor in context","b":"201–210","g":"VO"},{"n":32,"t":"mc","s":"“When he heard the result, his face fell.” What does this idiom mean?","o":["He fell over backwards in surprise.","He began to cry.","He looked suddenly disappointed.","He laughed loudly."],"k":"C","sk":"Interprets idiom in context","b":"201–210","g":"VO"},{"n":33,"t":"mc","s":"The root **cred** means “believe.” Which word describes a reason or source that can be trusted?","o":["creed","incredulous","credit","credible"],"k":"D","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"211–220","g":"VO"},{"n":34,"t":"mc","s":"Read the sentence. “The hikers were **resilient**; even after the storm destroyed their camp, they rebuilt it and kept going.” What does **resilient** mean?","o":["able to recover from difficulties","unable to move after the storm","careless with their equipment","easily frightened by danger"],"k":"A","sk":"Uses context to determine word meaning","b":"211–220","g":"VO"},{"n":35,"t":"mc","s":"Which word suggests the MOST extreme anger?","o":["bothered","irritated","furious","annoyed"],"k":"C","sk":"Analyzes nuances in meaning among related words","b":"211–220","g":"VO"},{"n":36,"t":"mc","s":"In which sentence does **mean** express “unkind”?","o":["What does this difficult word mean in English?","It was mean of him to laugh at the new boy.","I mean to finish the project tonight.","The mean of 4, 6 and 8 is 6."],"k":"B","sk":"Determines which meaning of a multiple-meaning word fits","b":"211–220","g":"VO"},{"n":37,"t":"mc","s":"Which word BEST completes the sentence? “The roads were flooded; ___, the school was closed for two days.”","o":["similarly","for example","nevertheless","consequently"],"k":"D","sk":"Words that show a cause-effect relationship","b":"211–220","g":"VO"},{"n":38,"t":"mc","s":"The prefix **counter-** means “against.” A **counterattack** is —","o":["a plan made before a battle","an attack made in response to an attack","a friendly meeting between two enemies","an attack that never happens"],"k":"B","sk":"Uses a defined root and/or affix to determine word meaning","b":"221–230","g":"VO"},{"n":39,"t":"mc","s":"Read the paragraph. “At first, the plan seemed **feasible**. We had enough money, enough time and enough volunteers. Only later did we learn that the hall was already booked.” What does **feasible** mean?","o":["very exciting","already finished","possible to do","too expensive"],"k":"C","sk":"Uses paragraph-level context to determine word meaning","b":"221–230","g":"VO"},{"n":40,"t":"mc","s":"Which word has the most NEGATIVE connotation?","o":["stubborn","persistent","determined","tenacious"],"k":"A","sk":"Understands precise connotations of words","b":"221–230","g":"VO"},{"n":41,"t":"mc","s":"The root **vid/vis** means “see.” Which word means “proof that can be seen or shown”?","o":["divide","provide","evidence","avoid"],"k":"C","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"221–230","g":"VO"},{"n":42,"t":"mc","s":"Which analogy is CORRECT? **Drought** is to **rain** as **famine** is to —","o":["food","heat","water","wind"],"k":"A","sk":"Uses analogies to understand word relationships","b":"231–240","g":"VO"},{"n":43,"t":"mc","s":"“The final scene was a masterpiece of understatement: after losing everything, the hero said only, ‘Well, that was unlucky.’” What is **understatement**?","o":["giving human qualities to an object","comparing two things using “like” or “as”","describing something as much bigger than it really is","describing something as less serious than it really is"],"k":"D","sk":"Analyzes figurative language: understatement","b":"231–240","g":"VO"}]}]},{"id":"D","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"The Fisherman’s Net","genre":"poem","paras":["My grandfather mends nets at dusk,","His needle flashing, in and out;","He says a net is mostly holes,","And that is what it’s all about.","","“A net that holds too tight,” he says,","“Will tear the moment that it’s tried;","You leave the spaces for the sea,","And keep the silver fish inside.”","","I think of him when I hold on","Too hard to things I want to keep —","And try to leave a little space","For what moves through, and what runs deep."],"poem":true},"items":[{"n":1,"t":"mc","s":"According to the grandfather, what happens to a net that “holds too tight”?","o":["It catches far too many fish.","It tears as soon as it is used.","It becomes too heavy to lift.","It floats away on the waves."],"k":"B","sk":"Locates details in poetry","b":"201–210","g":"LT"},{"n":2,"t":"mc","s":"What does the grandfather mean by “a net is mostly holes”?","o":["Most of his nets have been lost at sea.","The net is very old, badly damaged and no longer useful for fishing.","Fishermen should not use nets with holes.","A net works because of its spaces, not only its threads."],"k":"D","sk":"Determines the meaning of a nonliteral phrase","b":"211–220","g":"LT"},{"n":3,"t":"mc","s":"How does the third stanza change the poem?","o":["It shows the speaker learning to fish.","It describes a sudden storm that damages the nets on the beach.","It applies the lesson about nets to the speaker’s own life.","It moves from evening to the next morning."],"k":"C","sk":"Analyzes how the organization of a poem affects its meaning","b":"221–230","g":"LT"},{"n":4,"t":"mc","s":"What does holding on “too hard” most likely refer to?","o":["trying to control people or things too tightly","pulling the heavy net too quickly from the water","gripping the fishing needle too firmly","holding a fish so that it cannot escape"],"k":"A","sk":"Interprets extended metaphor","b":"221–230","g":"LT"},{"n":5,"t":"mc","s":"What is the theme of the poem?","o":["Letting go a little can help us keep what matters.","The sea is dangerous for those who fish at dusk.","Fishing teaches patience better than any school.","Old nets should be replaced instead of mended."],"k":"A","sk":"Determines theme in poetry","b":"221–230","g":"LT"}]},{"passage":{"title":"Five-Day Weather Forecast: Taif","genre":"chart","paras":["**Taif — forecast for the coming week**","Sunday: sunny, high 31 °C, low 18 °C · Monday: sunny, high 33 °C, low 19 °C · Tuesday: thunderstorms possible, high 27 °C, low 17 °C, chance of rain 60% · Wednesday: cloudy, high 28 °C, low 16 °C, chance of rain 20% · Thursday: sunny, high 32 °C, low 19 °C","*Flash flood warning: avoid wadis on any day when the chance of rain is above 50%.*"]},"items":[{"n":6,"t":"mc","s":"What is the purpose of the warning in italics?","o":["to explain how thunderstorms are formed","to tell readers how to stay safe on rainy days","to advertise weekend trips to the wadis near Taif","to show which day will be the hottest"],"k":"B","sk":"Determines specific purpose of a text feature","b":"201–210","g":"IT"},{"n":7,"t":"mc","s":"On which day should people avoid wadis, according to the warning?","o":["Monday","Wednesday","Tuesday","Thursday"],"k":"C","sk":"Integrates information from graphics and text","b":"211–220","g":"IT"},{"n":8,"t":"mc","s":"On which day is the difference between the high and low temperature the GREATEST?","o":["Thursday","Sunday","Tuesday","Monday"],"k":"D","sk":"Analyzes quantitative information in informational text","b":"221–230","g":"IT"},{"n":9,"t":"mc","s":"A family wants a sunny day for a picnic with the coolest high temperature. Which day should they choose?","o":["Sunday","Wednesday","Thursday","Monday"],"k":"A","sk":"Integrates information from a text feature","b":"221–230","g":"IT"},{"n":10,"t":"mc","s":"What is the most likely reason the temperature drops on Tuesday?","o":["The forecast uses a different scale on Tuesday.","Clouds and storms block sunlight and bring cooler air.","The wind always changes direction on Tuesdays.","Tuesday is the official first day of winter in the city of Taif."],"k":"B","sk":"Makes inferences from informational text","b":"221–230","g":"IT"}]},{"passage":{"title":"The Return","genre":"story","paras":["The school had changed. The playground where Faisal had once scraped both knees was now a car park, and the old mulberry tree by the gate had been cut down. He stood at the gate in his new uniform — not as a student this time, but as the new science teacher.","Twenty years earlier, he had been the boy at the back of the class who never finished his homework. He remembered Mr. Yaqub, the old science teacher, stopping beside his desk one afternoon after a failed test. Faisal had expected anger. Instead, Mr. Yaqub had put a small magnet and a handful of paper clips on the desk. “Show me what this can do,” he had said. “Then you can tell me why.” Faisal had stayed after school that day for the first time in his life.","Now, in his own classroom, Faisal looked at thirty faces. In the back row, a boy was drawing on the cover of his notebook, not listening. Faisal walked down the aisle, stopped beside his desk and placed a magnet and a few paper clips in front of him.","“Show me what this can do,” he said."]},"items":[{"n":11,"t":"mc","s":"How is the story structured?","o":["It begins with the ending and then explains the cause.","It tells the same event from the points of view of two teachers.","It begins in the present, moves back to a memory, then returns to the present.","It tells events in order, from Faisal’s early childhood all the way to his old age."],"k":"C","sk":"Analyzes flashback as a structure","b":"211–220","g":"LT"},{"n":12,"t":"mc","s":"Why does the author describe the car park and the missing mulberry tree?","o":["to show that the school has become richer","to explain why Faisal now dislikes the school that he once attended","to describe where Faisal parks his car each day","to show how much time has passed and how things have changed"],"k":"D","sk":"Analyzes how setting details contribute to meaning","b":"211–220","g":"LT"},{"n":13,"t":"mc","s":"Why was Mr. Yaqub’s response to the failed test important to young Faisal?","o":["It showed him that tests did not matter at all.","It sparked his curiosity instead of punishing him.","It embarrassed him in front of the whole class.","It made him decide to leave science forever."],"k":"B","sk":"Analyzes how events shape characters","b":"221–230","g":"LT"},{"n":14,"t":"mc","s":"What is significant about Faisal repeating Mr. Yaqub’s words at the end?","o":["He has forgotten what he had planned to teach the class that day.","He is copying his old teacher because he lacks ideas.","He is passing on the same kindness that changed his own life.","He wants to test whether the boy remembers Mr. Yaqub."],"k":"C","sk":"Analyzes how an ending contributes to meaning","b":"221–230","g":"LT"},{"n":15,"t":"mc","s":"Which theme does the story develop?","o":["Schools should always keep their old trees and their old playgrounds.","Students who fail tests should be punished firmly.","Science is the most important subject in school.","A teacher’s belief in a student can shape a life and be passed on."],"k":"D","sk":"Analyzes the development of theme in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"The Interview Panel","genre":"drama","paras":["*(A small office. Three judges sit behind a table: MS. NOURA, MR. ESSAM and MR. KAMAL. A student, ZIYAD, 15, has just finished speaking.)*","MR. ESSAM: Thank you, Ziyad. *(The boy leaves.)* Well, his grades are excellent. Top of his year.","MS. NOURA: *(looking at her notes)* Yes. But when I asked him about a time he failed, he said he had never failed.","MR. KAMAL: Perhaps he hasn’t.","MS. NOURA: *(smiling slightly)* Everyone has. The question is whether he has learned to notice it.","MR. ESSAM: And the girl before him? Her grades were lower.","MS. NOURA: She told us about the science project that collapsed the night before the fair, and what she rebuilt the next morning. *(She closes her folder.)* I know which of them I would trust with a problem nobody has solved yet.","*(A pause. MR. KAMAL slowly crosses out a number on his sheet.)*"]},"items":[{"n":16,"t":"mc","s":"What is the judges’ disagreement about?","o":["whether excellent grades matter more than the ability to learn from failure","whether Ziyad was telling the truth about his grades","whether the girl should be interviewed a second time","whether the interview room is large enough for the three judges on the panel"],"k":"A","sk":"Identifies conflict in literary text","b":"211–220","g":"LT"},{"n":17,"t":"mc","s":"How is Ms. Noura’s view DIFFERENT from Mr. Essam’s?","o":["She values how a candidate responds to setbacks; he focuses on grades.","She values grades most; he focuses on how a candidate handles failure.","She wants to interview more students; he wants to finish quickly.","She prefers Ziyad; he prefers the girl."],"k":"A","sk":"Compares or contrasts characters","b":"211–220","g":"LT"},{"n":18,"t":"mc","s":"What does Ms. Noura imply when she says, “Everyone has”?","o":["The judges themselves have failed in their careers.","The question about failure was unfair to Ziyad.","Ziyad’s answer suggests he does not reflect honestly on his mistakes.","Ziyad must have failed many exams in secret without telling his parents."],"k":"C","sk":"Makes inferences from literary text","b":"221–230","g":"LT"},{"n":19,"t":"mc","s":"What does the final stage direction suggest?","o":["Mr. Kamal has made a mistake adding the scores.","Mr. Kamal is preparing to leave the room.","Mr. Kamal disagrees strongly with Ms. Noura.","Mr. Kamal has been persuaded to change his score."],"k":"D","sk":"Analyzes use of stage directions","b":"221–230","g":"LT"},{"n":20,"t":"mc","s":"What theme does the scene explore?","o":["Interview panels should never disagree with each other in public.","Learning from failure can matter more than a perfect record.","Science projects should be finished long before a fair.","Students with high grades always succeed in life."],"k":"B","sk":"Determines theme in literary text","b":"221–230","g":"LT"}]},{"passage":{"title":"Living Light","genre":"informational","paras":["On some nights, the waves along certain beaches glow a ghostly blue. The light comes from tiny living organisms, and the phenomenon is called **bioluminescence**: light produced by a living thing.","Bioluminescence happens when a chemical called luciferin reacts with oxygen, helped by an enzyme. The reaction releases energy as light rather than heat, which is why bioluminescent creatures stay cool. Most of this light is blue or green, because those colours travel furthest through sea water.","Animals use their light for many purposes. Some deep-sea fish dangle a glowing lure to attract prey. Some squid produce light on their undersides to match the faint light from above, so that predators below cannot see their shadow. Fireflies, on land, flash patterns of light to find mates.","Scientists have borrowed this natural chemistry for medicine and research. By attaching light-producing genes to cells, researchers can watch how diseases spread or whether a treatment is working, simply by observing where the cells glow."]},"items":[{"n":21,"t":"mc","s":"What is the central idea of the text?","o":["Deep-sea fish are more dangerous than animals on land.","Ocean waves glow blue at night because they reflect the light of the full moon.","Bioluminescence is light made by living things, used in nature and by scientists.","Fireflies are the only animals that produce their own light."],"k":"C","sk":"Determines main/central idea in informational text","b":"211–220","g":"IT"},{"n":22,"t":"mc","s":"How does the third paragraph develop the topic?","o":["by describing how scientists use the light in medicine","by explaining the chemical reaction that produces light step by step","by comparing light in the ocean with light on land","by giving examples of the different purposes of animal light"],"k":"D","sk":"Analyzes how specific paragraphs contribute to meaning","b":"211–220","g":"IT"},{"n":23,"t":"mc","s":"Why do bioluminescent creatures stay cool, according to the text?","o":["The reaction releases energy as light rather than heat.","Their light is blue, which is a cool colour.","They live only in very cold and very deep parts of the ocean.","They produce light only at night."],"k":"A","sk":"Understands explicit relationships between ideas","b":"221–230","g":"IT"},{"n":24,"t":"mc","s":"How does a squid’s light protect it from predators below?","o":["It attracts other squid to help defend it.","It matches the faint light above so its shadow cannot be seen.","It warns predators that the squid is poisonous.","It blinds the predators below with a sudden and very bright flash."],"k":"B","sk":"Analyzes implicit relationships between ideas","b":"221–230","g":"IT"},{"n":25,"t":"mc","s":"Why does the author end with the use of light-producing genes?","o":["to prove that diseases glow when they spread","to explain why fireflies flash patterns of light","to warn readers about the dangers of genetic research in modern medicine","to show that a natural process has practical value for people"],"k":"D","sk":"Analyzes the purpose of an ending","b":"221–230","g":"IT"}]},{"passage":{"title":"Our Cities Should Plant Native Trees","genre":"argument","paras":["Walk through many new neighbourhoods and you will see rows of imported trees and wide green lawns. They look attractive, but in a desert climate they are thirsty and costly. City councils should plant mainly native trees and plants, such as the ghaf, the sidr and the acacia.","Native plants are adapted to heat and little rain. Once established, many need far less water than imported species, which is important in a country that relies heavily on desalinated water.","Native trees also support local wildlife. Birds, bees and insects that evolved alongside these plants depend on them for food and shelter. An imported tree may look green, but it may offer little to the creatures around it.","Some people argue that native trees grow slowly and look less impressive. Certain native species do grow slowly at first. But a tree is planted for decades, not for a single season, and many native trees provide wide shade once mature.","Planting native trees is not just about appearance. It is about choosing a city that can live with its climate rather than fight it."]},"items":[{"n":26,"t":"mc","s":"What is the author’s claim?","o":["City councils should plant mainly native trees and plants.","City councils should import more trees from other countries.","City councils should remove all lawns from neighbourhoods.","City councils should stop using desalinated water."],"k":"A","sk":"Determines author’s main argument or claim","b":"211–220","g":"IT"},{"n":27,"t":"mc","s":"Which reason is connected to the use of desalinated water?","o":["Native trees provide food and shelter for local wildlife.","Native plants need far less water once established.","Imported trees look attractive in new neighbourhoods.","Native trees provide wide shade once they are mature."],"k":"B","sk":"Identifies reasons that support a claim","b":"211–220","g":"IT"},{"n":28,"t":"mc","s":"How does the author respond to the counterclaim about slow growth?","o":["by suggesting that the city plant only fast-growing species","by denying that any native trees grow slowly, even in their first years","by conceding the point but arguing that trees are planted for decades","by ignoring it and repeating the first reason"],"k":"C","sk":"Identifies a counterclaim and rebuttal","b":"221–230","g":"IT"},{"n":29,"t":"mc","s":"What does the final sentence suggest about the author’s view?","o":["Cities should adapt to their environment instead of struggling against it.","Cities should be built only in places where there is plenty of rain all year.","Cities should plant trees only for their beauty.","Cities should spend more money on making streets attractive."],"k":"A","sk":"Determines the meaning of a nonliteral phrase","b":"221–230","g":"IT"},{"n":30,"t":"mc","s":"Which evidence would MOST strengthen the second paragraph?","o":["a description of the author’s own garden","data comparing the water needs of native and imported trees","a list of countries that export trees","a photograph of a large green lawn in a new neighbourhood of the city"],"k":"B","sk":"Evaluates evidence used to support claims","b":"221–230","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"“The teacher’s words were music to my ears.” What does this idiom mean?","o":["The words were far too loud to bear.","The teacher spoke very slowly.","The words were very pleasing to hear.","The teacher was singing a song."],"k":"C","sk":"Interprets idiom in context","b":"201–210","g":"VO"},{"n":32,"t":"mc","s":"“He has a heart of stone.” What does this metaphor suggest about him?","o":["He collects unusual stones.","He is physically very strong.","He has a serious heart illness.","He shows no sympathy or kindness."],"k":"D","sk":"Interprets metaphor in context","b":"201–210","g":"VO"},{"n":33,"t":"mc","s":"Read the sentence. “The pilot had to **abort** the landing because a truck was on the runway.” What does **abort** mean?","o":["to speed up suddenly","to stop before finishing","to repeat many times","to complete successfully"],"k":"B","sk":"Uses context to determine word meaning","b":"211–220","g":"VO"},{"n":34,"t":"mc","s":"Which word BEST completes the sentence? “Rami had trained for months; ___, he finished the race in record time.”","o":["on the other hand","in contrast","as a result","nevertheless"],"k":"C","sk":"Words that show a cause-effect relationship","b":"211–220","g":"VO"},{"n":35,"t":"mc","s":"The root **voc** means “call.” A **vocation** is —","o":["a long holiday that families take together in the summer","a loud noise made by an animal","a lesson about speaking clearly","a type of work that someone feels called to do"],"k":"D","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"221–230","g":"VO"},{"n":36,"t":"mc","s":"Which word suggests the MOST extreme degree of cold?","o":["frigid","cool","chilly","brisk"],"k":"A","sk":"Analyzes nuances in meaning among related words","b":"221–230","g":"VO"},{"n":37,"t":"mc","s":"In which sentence does **settle** mean “to decide or resolve”?","o":["Settle into your seats before the film starts.","Many families settled near the river.","The dust began to settle after the storm.","The two companies agreed to settle the dispute."],"k":"D","sk":"Determines which meaning of a multiple-meaning word fits","b":"221–230","g":"VO"},{"n":38,"t":"mc","s":"The prefix **omni-** means “all.” An **omnivore** is an animal that eats —","o":["only insects","both plants and animals","only plants, such as grass and leaves","only meat"],"k":"B","sk":"Uses a defined root and/or affix to determine word meaning","b":"221–230","g":"VO"},{"n":39,"t":"mc","s":"Read the paragraph. “The two reports **contradicted** each other. One said the bridge was safe; the other said it should be closed at once.” What does **contradicted** mean?","o":["repeated the words of","added details to","said the opposite of","agreed completely with"],"k":"C","sk":"Uses paragraph-level context to determine word meaning","b":"221–230","g":"VO"},{"n":40,"t":"mc","s":"Which word has the most POSITIVE connotation?","o":["frugal","cheap","stingy","miserly"],"k":"A","sk":"Understands precise connotations of words","b":"221–230","g":"VO"},{"n":41,"t":"mc","s":"The root **chron** means “time.” A **chronic** illness is one that —","o":["happens only once in a life","lasts for a long time","is easy to cure","is very mild"],"k":"B","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"221–230","g":"VO"},{"n":42,"t":"mc","s":"“The silence after the announcement was deafening.” Which figurative device combines opposite ideas here?","o":["simile","onomatopoeia","paradox","alliteration"],"k":"C","sk":"Interprets paradox in context","b":"231–240","g":"VO"},{"n":43,"t":"mc","s":"Which analogy is CORRECT? **Meticulous** is to **careless** as **generous** is to —","o":["selfish","polite","kind","wealthy"],"k":"A","sk":"Uses analogies to understand word relationships","b":"231–240","g":"VO"}]}]},{"id":"E","note":"Final full practice test · 43 questions · hardest","sections":[{"passage":{"title":"How al-Biruni Measured the Earth","genre":"informational","paras":["About a thousand years ago, the scholar Abu Rayhan al-Biruni set out to answer a question that had challenged thinkers for centuries: how big is the Earth?","Earlier scholars had measured the Earth by comparing the position of the Sun or stars from two distant cities, a method that required long journeys and accurate measurement of distance across land. Al-Biruni found a method that could be done from a single place.","First, he measured the height of a mountain using trigonometry, the mathematics of triangles. Then he climbed to the top and measured the angle at which the horizon dipped below the level of his eye. Because the Earth is curved, the horizon appears slightly lower than straight ahead. Using the mountain’s height and this tiny angle, he calculated the Earth’s radius.","His result was remarkably close to the modern value, which is about 6,371 kilometres; most accounts place his estimate within about one per cent of it. His work shows how careful observation and mathematics could reveal the size of the whole planet from the top of a single mountain."]},"items":[{"n":1,"t":"mc","s":"How is the third paragraph organized?","o":["as a problem with several solutions","as a description of a mountain","as a comparison of two scholars","as a sequence of steps in a method"],"k":"D","sk":"Identifies process as a structure","b":"211–220","g":"IT"},{"n":2,"t":"mc","s":"What was the main advantage of al-Biruni’s method over earlier methods?","o":["It could be carried out from a single location.","It measured the Earth’s weight as well as its size.","It required no mathematics at all.","It used the stars instead of the Sun."],"k":"A","sk":"Compares or contrasts details/ideas","b":"221–230","g":"IT"},{"n":3,"t":"mc","s":"Why does the horizon appear slightly lower than eye level from a mountain top?","o":["because the Sun is setting","because the Earth is curved","because the mountain is leaning","because the air is thin at the top"],"k":"B","sk":"Determines the cause of a situation","b":"221–230","g":"IT"},{"n":4,"t":"mc","s":"Which TWO measurements did al-Biruni combine to calculate the radius?","o":["the mountain’s width and the height of the clouds","the distance between two cities and the angle of the Sun","the mountain’s height and the angle of the horizon’s dip","the length of a shadow and the time of day"],"k":"C","sk":"Understands sequence in informational text","b":"221–230","g":"IT"},{"n":5,"t":"mc","s":"What does the word **remarkably** suggest about the author’s view of al-Biruni’s result?","o":["The author is impressed by how accurate it was.","The author believes the result was a lucky guess.","The author thinks the method was too simple.","The author doubts that the result is correct."],"k":"A","sk":"Determines author’s attitude in informational text","b":"221–230","g":"IT"}]},{"passage":{"title":"The Inheritance","genre":"story","paras":["When old Hajj Mubarak died, his three sons gathered in the courtyard to hear his will. Everyone in the village knew he had been rich once. Everyone also knew that, in his last years, he had spent most of his days in a small workshop behind the house, mending broken furniture for neighbours who could not afford new.","The lawyer read slowly. To the eldest son, Majed, who lived in the city and visited once a year, he left the house. To the second son, Saud, who had argued with him about money, he left the farm. To the youngest, Hamad, who had spent every afternoon in the workshop beside him, he left “my tools, and everything they have taught me.”","Saud laughed. “Old tools. That is all you get for wasting your youth in a workshop.” Hamad said nothing.","Within two years, Majed had sold the house to pay his debts in the city. Saud’s farm, badly managed, was failing. Hamad’s workshop, meanwhile, had become the busiest in three villages. People brought him chairs and doors and old wooden chests, and paid him well, because he did the work the way his father had taught him: slowly, honestly and well.","One evening, Saud came to the workshop, looking tired. He picked up a plane, turned it over in his hands and set it down. “He gave you the best part,” he said quietly. Hamad handed him a piece of sandpaper. “He gave all of us something,” he said. “Some of us just needed longer to see it.”"]},"items":[{"n":6,"t":"mc","s":"What is ironic about Saud’s comment “That is all you get”?","o":["Hamad already owned better tools than his father’s.","The tools turn out to be the most valuable inheritance of all.","Saud himself had always wanted the tools more than he wanted the farm.","The lawyer had read the will to the wrong son."],"k":"B","sk":"Analyzes situational irony","b":"221–230","g":"LT"},{"n":7,"t":"mc","s":"Why does the author describe how each son related to his father?","o":["to describe how the village viewed the three brothers","to show that the lawyer did not know the family well","to explain why the father was no longer rich in the last years of his life","to suggest that each inheritance matched the relationship and its lessons"],"k":"D","sk":"Analyzes how specific details contribute to plot","b":"221–230","g":"LT"},{"n":8,"t":"mc","s":"What does the phrase “everything they have taught me” suggest about the inheritance?","o":["Hamad inherits the money his father earned from repairs.","Hamad inherits his father’s books about carpentry.","Hamad inherits skills and values as well as objects.","Hamad must teach his brothers how to use the tools."],"k":"C","sk":"Determines the meaning of a nonliteral phrase","b":"221–230","g":"LT"},{"n":9,"t":"mc","s":"What does Saud’s action of turning the plane over in his hands suggest?","o":["He is checking whether the tool is broken.","He wants to sell the tools to pay for the farm.","He is planning to take the workshop from Hamad.","He is reconsidering what his father truly valued."],"k":"D","sk":"Makes inferences from literary text","b":"221–230","g":"LT"},{"n":10,"t":"mc","s":"How does Hamad’s final reply develop the theme?","o":["It suggests that wisdom passed down can still be learned, even late.","It suggests that tools are more valuable than land.","It suggests that Saud should leave the village and never come back again.","It suggests that the father loved Hamad more than the others."],"k":"A","sk":"Analyzes the development of theme in literary text","b":"231–240","g":"LT"}]},{"passage":{"title":"The Translator’s Choice","genre":"drama","paras":["*(A hospital corridor at night. NASSER, 16, sits beside an elderly man, MR. LIM, a visitor from abroad who speaks no Arabic. A DOCTOR approaches with a clipboard.)*","DOCTOR: You speak English? Good. Please tell him the results are serious. He will need an operation tomorrow, and there are risks.","*(NASSER turns to MR. LIM. He hesitates. MR. LIM looks frightened.)*","NASSER: *(slowly, in English)* The doctor says… you need an operation. Tomorrow.","MR. LIM: *(gripping the arm of his chair)* Is it dangerous? Tell me the truth.","*(NASSER looks at the DOCTOR, then back at MR. LIM.)*","NASSER: *(after a long pause)* He says there are risks. But he says it is the right thing to do, and that you are in the best place. I will stay until your family arrives.","MR. LIM: *(releasing the chair, quietly)* Thank you. You did not make it sound easy. That is why I believe you."]},"items":[{"n":11,"t":"mc","s":"What dilemma does Nasser face?","o":["whether to speak English or Arabic to the doctor","whether to call Mr. Lim’s family or the police","whether to soften the frightening news or tell the full truth","whether to stay at the hospital all night or go home to his own family"],"k":"C","sk":"Identifies conflict in literary text","b":"221–230","g":"LT"},{"n":12,"t":"mc","s":"Why do the stage directions mention that Mr. Lim grips and later releases the chair?","o":["to show that he wants to stand up and leave","to show his fear and then his relief","to show that he is in physical pain","to show that the chair is uncomfortable"],"k":"B","sk":"Analyzes use of stage directions","b":"221–230","g":"LT"},{"n":13,"t":"mc","s":"How does Nasser handle the translation?","o":["He hides the risks so that Mr. Lim will not worry.","He asks the doctor to explain everything again, much more slowly.","He refuses to translate because the news is too serious.","He tells the truth about the risks but adds comfort and support."],"k":"D","sk":"Analyzes how a character responds to challenges","b":"221–230","g":"LT"},{"n":14,"t":"mc","s":"Which theme does the scene develop?","o":["Honesty delivered with compassion builds trust.","Hospitals should hire professional translators.","Young people should not be involved in medical decisions.","Operations are always dangerous for elderly patients."],"k":"A","sk":"Determines theme in literary text","b":"221–230","g":"LT"},{"n":15,"t":"mc","s":"What does Mr. Lim mean by “You did not make it sound easy. That is why I believe you.”?","o":["Mr. Lim did not understand Nasser’s English and wanted to hear it again.","Mr. Lim thinks the operation will be simple.","Nasser’s honesty about the danger makes his reassurance trustworthy.","Mr. Lim wants Nasser to explain the results again."],"k":"C","sk":"Analyzes dialogue to understand theme","b":"231–240","g":"LT"}]},{"passage":{"title":"Why False Stories Spread So Fast","genre":"informational","paras":["A rumour that a famous actor has died, a photograph of a shark swimming down a flooded motorway, a message warning that a common food causes illness: false stories travel quickly online, and they often travel faster than the truth.","One reason is emotion. Studies of social media have found that posts which provoke strong feelings such as surprise, fear or anger are shared more often. False stories are frequently designed to do exactly that, while accurate reports can seem ordinary by comparison.","Another reason is speed. Sharing takes a single tap, but checking a claim takes time and effort. Many people share a headline without reading the article, especially if it seems to confirm what they already believe.","Experts suggest a few simple habits: pause before sharing; check whether trusted news sources are reporting the same story; look at the date and the original source; and be most careful with posts that make you feel a strong emotion. As one researcher put it, the feeling of “I must share this now” is itself a warning sign."]},"items":[{"n":16,"t":"mc","s":"What is the central idea of the text?","o":["Most news shared online today is accurate and trustworthy.","False stories spread quickly because of emotion and speed, but simple habits can slow them.","Social media companies should immediately delete every post that contains any false information.","Photographs of sharks on motorways are usually real."],"k":"B","sk":"Determines main/central idea in informational text","b":"221–230","g":"IT"},{"n":17,"t":"mc","s":"Why does the author open with three examples of false stories?","o":["to warn readers not to eat certain common foods","to prove that famous actors are often the subject of false rumours online","to give readers familiar examples of the problem before explaining it","to show that floods are becoming more common in cities"],"k":"C","sk":"Analyzes the purpose of an introduction","b":"221–230","g":"IT"},{"n":18,"t":"mc","s":"How is the text organized?","o":["It tells the story of one false rumour from the moment it began to the very end.","It describes a problem, explains its causes and then offers solutions.","It lists famous false stories in order of when they appeared.","It compares newspapers with social media in each paragraph."],"k":"B","sk":"Describes the organizational structure of a text","b":"221–230","g":"IT"},{"n":19,"t":"mc","s":"According to the text, why might accurate reports spread more slowly?","o":["They often seem ordinary and provoke weaker emotions.","They are written by people who do not use social media.","They are usually much longer than false stories.","They are published only in printed newspapers."],"k":"A","sk":"Analyzes implicit relationships between ideas","b":"231–240","g":"IT"},{"n":20,"t":"mc","s":"What does the researcher mean by calling the urge to share “a warning sign”?","o":["People who share posts very quickly are usually dishonest and want to cause trouble.","Sharing news is always dangerous and should be avoided.","Phones should display warnings before every post is shared.","A strong emotional reaction is a reason to check a post more carefully."],"k":"D","sk":"Determines the meaning of a quotation","b":"231–240","g":"IT"}]},{"passage":{"title":"The River of Time","genre":"poem","paras":["They say that time is like a river,","And so it is — but not the kind","That runs in one long line forever","And leaves the stones of days behind.","","It loops, it pools, it doubles back;","An afternoon can last a year,","And years can vanish down a crack","Before we notice they were here.","","So I have learned to stop and stand","Where some slow, shining moment flows,","And cup a little in my hand","Before it slips, and on it goes."],"poem":true},"items":[{"n":21,"t":"mc","s":"“An afternoon can last a year.” What does this hyperbole suggest?","o":["The speaker once spent a whole year living in one place.","Some moments feel much longer than they really are.","The speaker has lost track of the calendar.","Afternoons are longer in the summer months."],"k":"B","sk":"Interprets hyperbole in context","b":"221–230","g":"LT"},{"n":22,"t":"mc","s":"What does the image of years vanishing “down a crack” suggest?","o":["Long periods can pass almost unnoticed.","The speaker has hidden something valuable.","The river is drying up in the summer.","The road beside the river is broken."],"k":"A","sk":"Analyzes the effect of imagery in context","b":"221–230","g":"LT"},{"n":23,"t":"mc","s":"How does the speaker change the familiar comparison “time is like a river”?","o":["by rejecting the comparison as completely false","by arguing that time is much more like a mountain than it is like a river","by explaining how rivers are formed over many years","by suggesting time does not always flow evenly in one direction"],"k":"D","sk":"Analyzes how an author transforms a familiar idea","b":"231–240","g":"LT"},{"n":24,"t":"mc","s":"What does the speaker mean by cupping “a little in my hand”?","o":["collecting stones from the riverbed as souvenirs","trying to stop the river from flowing","taking time to hold on to and appreciate a precious moment","collecting smooth stones from the riverbed to keep as souvenirs"],"k":"C","sk":"Interprets extended metaphor","b":"231–240","g":"LT"},{"n":25,"t":"mc","s":"What is the theme of the poem?","o":["People should keep careful diaries of every year.","Time moves faster for young people than for old.","Rivers are the most beautiful and important features of the natural world.","Because time passes unpredictably, we should savour meaningful moments."],"k":"D","sk":"Determines theme in poetry","b":"231–240","g":"LT"}]},{"passage":{"title":"Should Schools Use AI Tutors?","genre":"viewpoints","paras":["**Viewpoint 1 — Ms. Reem, school principal:** AI tutors can give every student help at any hour, at their own pace. In a class of thirty, a teacher cannot answer every question, but an AI tutor can explain a problem five different ways without losing patience. Used wisely, it frees teachers to focus on discussion, creativity and the students who need them most.","**Viewpoint 2 — Mr. Tariq, mathematics teacher:** An AI tutor can explain, but it can also simply give the answer, and many students will let it. Learning often happens in the struggle before the answer appears. I have also seen AI tools state wrong information with complete confidence. Students need to learn to think for themselves first, and to check what any machine tells them."]},"items":[{"n":26,"t":"mc","s":"What is Ms. Reem’s main argument?","o":["Teachers lose patience more often than machines do.","Classes of thirty students are too large for any school.","Used wisely, AI tutors can give students personal help and free teachers for other work.","AI tutors should replace classroom teachers in most subjects because they never lose patience."],"k":"C","sk":"Determines author’s main argument or claim","b":"221–230","g":"IT"},{"n":27,"t":"mc","s":"What kind of support does Mr. Tariq use for his claim about wrong information?","o":["a quotation from a technology company","his own observation as a teacher","statistics from a large study","the results of a school survey"],"k":"B","sk":"Evaluates evidence used to support claims","b":"221–230","g":"IT"},{"n":28,"t":"mc","s":"What concern does Mr. Tariq raise that Ms. Reem does not address?","o":["Students may skip the struggle that leads to real learning.","AI tutors cannot explain problems in different ways.","AI tutors are far too expensive for most schools to buy and maintain.","Teachers do not have time to learn new technology."],"k":"A","sk":"Compares and contrasts viewpoints in multiple texts","b":"231–240","g":"IT"},{"n":29,"t":"mc","s":"On which point might BOTH writers agree?","o":["AI tools should be banned from all schools until they are completely safe.","AI tools should be used carefully rather than without thought.","AI tools are useful only for mathematics.","AI tools always give correct information."],"k":"B","sk":"Synthesizes information found in multiple texts","b":"231–240","g":"IT"},{"n":30,"t":"mc","s":"Why does Ms. Reem include the phrase “Used wisely”?","o":["to show that she does not really trust AI tools to help students at all","to explain how AI tutors are designed and built","to acknowledge that the benefits depend on how the tools are used","to suggest that only wise students should use AI"],"k":"C","sk":"Analyzes how word choice advances purpose","b":"231–240","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Which word suggests the MOST serious kind of harm?","o":["dent","scratch","damage","devastate"],"k":"D","sk":"Analyzes nuances in meaning among related words","b":"221–230","g":"VO"},{"n":32,"t":"mc","s":"“After the long debate, the committee chose to bury the hatchet.” What does this idiom mean?","o":["to end a disagreement and make peace","to hide something valuable from other people","to vote on a decision","to start a new argument"],"k":"A","sk":"Interprets idiom in context","b":"221–230","g":"VO"},{"n":33,"t":"mc","s":"Read the sentence. “The two scientists had a **mutual** respect; each admired the other’s work.” What does **mutual** mean?","o":["kept secret","shared by both","felt by one only","newly formed"],"k":"B","sk":"Uses context to determine word meaning","b":"221–230","g":"VO"},{"n":34,"t":"mc","s":"The root **ben** means “good.” A **beneficiary** is a person who —","o":["receives money or help from something","gives money to a charity every year","writes a will for a family","manages a large company"],"k":"A","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"231–240","g":"VO"},{"n":35,"t":"mc","s":"Read the paragraph. “The speaker’s argument was **compelling**. Every point was supported by evidence, and by the end, even those who had disagreed were nodding.” What does **compelling** mean?","o":["long and repetitive","confusing and unclear","rude and aggressive","convincing and powerful"],"k":"D","sk":"Uses paragraph-level context to determine word meaning","b":"231–240","g":"VO"},{"n":36,"t":"mc","s":"In which sentence does **yield** mean “to produce”?","o":["Drivers must yield to people crossing the road.","The old door finally yielded to his push.","The new farm will yield a large harvest of dates.","The army refused to yield the city."],"k":"C","sk":"Determines which meaning of a multiple-meaning word fits","b":"231–240","g":"VO"},{"n":37,"t":"mc","s":"Which word BEST completes the sentence? “The evidence was incomplete; ___, the scientists refused to draw any firm conclusions.”","o":["meanwhile","however","likewise","accordingly"],"k":"D","sk":"Words that show a cause-effect relationship","b":"231–240","g":"VO"},{"n":38,"t":"mc","s":"The root **jud** means “judge.” A **prejudice** is —","o":["a fair judgement of both sides","a decision made by a judge in a court of law","an opinion formed before knowing the facts","a careful study of the evidence"],"k":"C","sk":"Applies knowledge of Greek or Latin roots in the 6-8 grade band","b":"231–240","g":"VO"},{"n":39,"t":"mc","s":"Which word has the most NEGATIVE connotation?","o":["strategy","scheme","design","plan"],"k":"B","sk":"Understands precise connotations of words","b":"231–240","g":"VO"},{"n":40,"t":"mc","s":"“The final exam was his **Waterloo**.” Waterloo was the battle where Napoleon suffered his final defeat. What does the allusion mean?","o":["The exam was where he was finally defeated.","The exam was the easiest one of the whole year.","The exam was about European history.","The exam was held in another country."],"k":"A","sk":"Interprets allusion in context","b":"231–240","g":"VO"},{"n":41,"t":"mc","s":"Which word means the OPPOSITE of **transparent** when describing a person’s motives?","o":["obvious","honest","hidden","clear"],"k":"C","sk":"Identifies antonyms in context","b":"231–240","g":"VO"},{"n":42,"t":"mc","s":"“To say the storm caused some inconvenience would be an understatement; it destroyed half the town.” What is the writer emphasising?","o":["that the damage was far greater than “inconvenience” suggests","that the storm was much less serious than people had reported","that the writer is unsure how bad the storm was","that the town recovered quickly after the storm"],"k":"A","sk":"Analyzes figurative language: understatement","b":"231–240","g":"VO"},{"n":43,"t":"mc","s":"Which analogy is CORRECT? **Novice** is to **expert** as **apprentice** is to —","o":["beginner","worker","student","master"],"k":"D","sk":"Uses analogies to understand word relationships","b":"231–240","g":"VO"}]}]}],"pass":[{"title":"The Captain’s Armband","genre":"story","paras":["When Coach Adel gave Hamza the captain’s armband, the changing room went quiet. Hamza was not the best player on the team. That was Fahd, who had scored twelve goals that season and who had expected the armband since the first day of training.","In the next match, Hamza called the players together before kick-off. “Let’s keep our shape,” he said. Fahd laughed. “Keep our shape? Just give me the ball and stay out of the way.” A few players smiled. Hamza felt his face burn, but he said nothing.","At half-time they were losing 2–0. Fahd had tried to dribble past the whole defence four times and lost the ball four times. In the changing room, he threw his water bottle against the wall. “Nobody is moving!” he shouted.","Hamza waited until the room was quiet. “You’re right,” he said to Fahd. “Nobody is moving, because everyone is waiting for you. So in the second half, you choose: we can all watch you, or you can make us better.” He did not raise his voice. Fahd stared at him, then looked away.","In the second half, Fahd passed the ball on his first touch. The team scored twice and drew 2–2. Afterwards, as they walked off, Fahd fell into step beside Hamza. “That was a good speech,” he admitted. “For someone who can’t shoot.” Hamza laughed. It was the first time all season they had laughed together."]},{"title":"The Letter","genre":"story","paras":["Rashid found the envelope in the drawer of his late grandfather’s desk. It was addressed to his father, sealed, and dated eleven years earlier — the year his father had moved to Riyadh after a bitter argument and stopped visiting the village.","Rashid knew about the argument only in pieces. His grandfather had wanted his father to take over the family farm. His father had wanted to study engineering. Words had been said that neither of them could take back. Then the grandfather had grown old, and then ill, and then he was gone.","Rashid held the letter for a long time. He wanted to open it. He also knew it was not his.","That evening, he gave it to his father. His father turned it over twice, as if it were very heavy. Then he went into the garden and read it alone. When he came back, his eyes were red, but his face looked lighter than Rashid had seen it in years.","“What did it say?” Rashid asked.","His father was quiet. “It said he was proud of me,” he said finally. “He wrote it the week I left. He just never sent it.” He put his hand on Rashid’s shoulder. “Don’t wait eleven years to say the important things.”"]},{"title":"The Accidental Discovery That Changed Medicine","genre":"informational","paras":["Before the 1940s, a small cut could be deadly. If bacteria entered a wound, there was often little doctors could do. Infections that are easily treated today, such as pneumonia or an infected scratch, killed many people every year.","**A Lucky Mistake**","In 1928, the Scottish scientist Alexander Fleming returned from a holiday to find that mould had grown on one of his dishes of bacteria. Around the mould, the bacteria had died. Fleming realised that the mould was producing a substance that killed bacteria. He named it **penicillin**.","**From Discovery to Medicine**","Fleming could not produce penicillin in large amounts, and for about ten years his discovery attracted little attention. Then, during the Second World War, a team at the University of Oxford found ways to purify it and test it on patients. Factories soon produced it in large quantities, and it saved many soldiers and civilians.","**A Growing Problem**","Antibiotics transformed medicine, but they have a weakness. When they are used too often or not finished properly, some bacteria survive and pass on their ability to resist the drug. This **antibiotic resistance** is now one of the world’s most serious health threats. Doctors therefore urge people to take antibiotics only when they are prescribed, and to complete the full course."]},{"title":"The Silk Roads","genre":"informational","paras":["The name “Silk Road” suggests a single highway running from China to Europe. In reality, the Silk Roads were a vast network of land and sea routes that connected Asia, the Middle East, Africa and Europe for well over a thousand years.","Few traders travelled the whole distance. Instead, goods passed from hand to hand, from one city or port to the next. Silk, paper and porcelain moved west from China; glass, wool and silver moved east. Arabian merchants carried frankincense, while spices from India reached the markets of Baghdad and Cairo.","But the routes carried far more than goods. Along them travelled religions, languages, inventions and ideas. The technique of making paper, for example, spread from China to the Islamic world in the eighth century, and later to Europe. Mathematical ideas, medical knowledge and artistic styles moved in the same way.","The routes also carried less welcome travellers. In the fourteenth century, a deadly plague is believed to have spread along trade routes, killing a large share of the population in many regions. The same connections that brought wealth and knowledge could also bring disaster.","Today, the Silk Roads remind us that the world has long been connected, and that connection brings both opportunity and risk."]},{"title":"Words Under the Microscope","genre":"sentences","paras":["Knowing a root helps you unlock many words: **cred** means *believe*, so a **credible** witness is one you can believe.","Related words carry different shades of meaning. *Thin*, *slim*, *skinny* and *scrawny* all describe a small body, but each sounds different.","An **allusion** is a short reference to a well-known story or person. Calling a task “Herculean” suggests it needs the strength of the hero Hercules.","An **analogy** shows a relationship: *glove* is to *hand* as *sock* is to *foot*."]},{"title":"The Perfect Plan","genre":"story","paras":["Khalid had planned everything. His father’s fiftieth birthday was on Thursday, and for once the surprise would be perfect. He had told his father a lie that seemed harmless: that he had a football match on Thursday evening and would be home late.","On Wednesday night, his father looked up from the newspaper. “Thursday’s match,” he said. “Is it at the school ground?” Khalid nodded quickly. “I might come and watch,” his father said. Khalid’s stomach dropped. “No need,” he said. “It’s just a practice match.” His father smiled and returned to the paper.","On Thursday, Khalid and his mother decorated the house, while his uncles arranged the food. At seven o’clock, the guests hid in the dark living room, waiting for the sound of the front door. Seven-thirty came, then eight. Nobody came.","At eight-fifteen, Khalid’s phone rang. It was his father. “I’m at the school ground,” he said, sounding puzzled. “I came to surprise you and watch your match. But the gates are locked, and there’s nobody here.”","Khalid closed his eyes. Behind him, thirty guests were trying very hard not to laugh."]},{"title":"The Glassblower","genre":"poem","paras":["He takes the molten sun of glass","Upon the long end of his pipe,","And breathes into it, slow, and then —","It swells, a fruit not yet quite ripe.","","He turns it in the furnace mouth,","He shapes it with a wooden spoon;","He does not hurry, does not force,","He lets it cool beneath the moon.","","My teacher, too, has breathed in me","Through years of patience, word by word;","And what I am, I could not see","Until his quiet shaping stirred."],"poem":true},{"title":"Public Transport Should Be Free","genre":"argument","paras":["Every morning, thousands of cars crawl along our city’s main roads, most carrying a single person. Meanwhile, buses run half-empty. The city should make all buses and metro trains free to use.","First, free transport would reduce congestion. When the city of Tallinn in Estonia made public transport free for residents in 2013, the number of passengers rose. If even a fraction of drivers in our city switched to the metro, traffic would move faster for everyone.","Second, fewer cars would mean cleaner air. Vehicle emissions are a major source of air pollution in large cities, and pollution is linked to breathing problems such as asthma.","Critics argue that free transport is too expensive, because the city would lose the money it collects from fares. However, fares cover only part of the cost of running the system; the city already subsidises it heavily. The extra cost could be balanced by savings on road repairs and health care.","Finally, my cousin, who lives in Tallinn, says the city is very beautiful in winter. Free transport is the future, and the sooner we begin, the better."]},{"title":"Zoos: Protectors or Prisons?","genre":"argument","paras":["Few places attract families like a zoo. But behind the excitement lies a serious question: should we keep wild animals in captivity? Modern, well-run zoos are essential for protecting wildlife, and they deserve public support.","First, zoos help save species from extinction. Breeding programmes have helped return animals such as the Arabian oryx to the wild after they had disappeared from their natural habitat. Without carefully managed captive populations, some species would no longer exist.","Second, zoos support research and education. Scientists learn about animal health and behaviour in ways that are difficult in the wild, and millions of visitors learn to care about animals they would never otherwise see.","Critics argue that zoos are prisons, and that animals suffer in small enclosures. It is true that some zoos have treated animals badly, and those zoos should be closed. But this is an argument for better zoos, not for no zoos. Accredited zoos must meet strict standards for space, diet and care.","Animals are wonderful, and everyone loves seeing a lion up close. That is why we should protect and fund our zoos."]},{"title":"Text 1: First Solo · Text 2: How a Wing Lifts a Plane","genre":"paired","paras":["**Text 1: First Solo (a narrative)**","The instructor climbed out and shut the door. “Just one circuit,” she said through the window. “You’re ready.” Suddenly the seat beside me looked enormous. I pushed the throttle forward, and the little plane rolled faster and faster down the runway. I eased back on the controls, and the ground simply let go of us. For a moment I forgot to breathe. The wings, which I had walked around a hundred times on the ground, now seemed to be holding the whole sky underneath them.","**Text 2: How a Wing Lifts a Plane (an article)**","An aeroplane flies because its wings produce **lift**, an upward force. A wing is shaped and tilted so that it pushes air downward as it moves forward. By Newton’s third law, the air pushes back up on the wing. The air flowing over the curved top of the wing also moves faster than the air underneath, which lowers the pressure above the wing. Lift depends on speed: a plane must travel fast enough along the runway before its wings can produce enough lift to overcome its weight. That is why pilots wait for a particular speed before raising the nose."]},{"title":"Text 1: The Night of the Dust · Text 2: Dust Storms and Health","genre":"paired","paras":["**Text 1: The Night of the Dust (a narrative)**","My younger brother Talal has asthma. Usually it is mild, and we almost forget it. But on the night the dust storm came, the air in our house turned grey, and even with the windows shut I could taste sand. Talal began to cough, then to wheeze. My mother found his inhaler and sat with him by the air purifier, counting his breaths in a calm voice that I knew was not calm at all. By morning the storm had passed. Talal was asleep at last, and my mother was still sitting beside him.","**Text 2: Dust Storms and Health (an article)**","Dust storms carry fine particles that can travel deep into the lungs. For most healthy people, the effects are short-lived: irritated eyes, coughing or a sore throat. For people with asthma or other breathing conditions, however, dust can trigger serious attacks. Health authorities advise staying indoors with windows and doors closed, using air purifiers where possible, and keeping prescribed medicines close at hand. Hospitals in dusty regions often report more visits for breathing problems during and just after major storms."]}]};
(function(d){d.units.forEach(function(u){u.sets.forEach(function(s){s.passage=s.p==null?null:d.pass[s.p];});});})(window.MAP_DATA["reading_8"]);
